//! Painter style profiles: which tools a painter reaches for and how they
//! handle them. Written from knowledge of the painter, never from images.
//!
//! A `Style` is data: a support and ground, a tool kit and handling
//! parameters for the kinds of passage a painting is made of (sky, body of a
//! form, detail, line, blending). Paintings ask the style for a `Handling`
//! and supply only geometry and color.

use crate::bristle::{Orient, Tool};
use crate::canvas::Canvas;
use crate::color::{Rgb, hex};
use crate::handling::Handling;
use crate::mask::Mask;
use crate::palette::Palette;
use crate::surface::Linen;

/// Mean thickness (µm) a brushed ground lays per unit of load with the
/// priming brush and coverage used in `Style::prepare` (measured: 0.2 → 36,
/// 0.35 → 67, 0.7 → 141 µm).
const BRUSHED_UM_PER_LOAD: f32 = 195.0;

/// How a ground layer is put on.
#[derive(Clone, Copy, Debug)]
pub enum Apply {
    /// Spread with a priming knife: levels the weave; `texture` 0..1 is the
    /// waviness of the knife.
    Knife { texture: f32 },
    /// Rolled on: a fine, even orange-peel texture.
    Roller,
    /// Brushed with a broad hog brush in horizontal strokes: striations stay.
    Brush,
}

/// One preparation layer.
#[derive(Clone, Copy, Debug)]
pub struct Ground {
    pub color: Rgb,
    pub hiding: f32,
    /// Thickness, µm.
    pub um: f32,
    /// Stiffness of the priming paste (0 fluid .. 1 stiff).
    pub stiff: f32,
    pub apply: Apply,
}

#[derive(Clone, Debug)]
pub struct Style {
    pub name: &'static str,
    /// Physical width of a typical canvas, mm.
    pub width_mm: f32,
    pub linen: Linen,
    /// Color of the raw linen.
    pub raw: Rgb,
    /// Preparation layers, bottom first.
    pub ground: Vec<Ground>,
    /// Tool for large atmospheric areas (sky, fog, water).
    pub broad: Tool,
    /// Tool for building forms (land, rocks, masses).
    pub body: Tool,
    /// Tool for small forms and edges.
    pub detail: Tool,
    /// Tool for lines: twigs, rigging, grasses.
    pub line: Tool,
    /// Tool for softening wet passages (None = the painter leaves strokes).
    pub blender: Option<Tool>,
    /// Blending passes over broad areas.
    pub blend_passes: usize,
    /// Pressure used when blending (light = gentle fusing).
    pub blend_pressure: f32,
    /// The tube paints this painter mixes everything from.
    pub palette: Palette,
    /// Fraction of oil medium in the paint for body passages and for thin,
    /// atmospheric passages.
    pub body_medium: f32,
    pub thin_medium: f32,
    /// How unevenly each pile is mixed (relative sd of proportions).
    pub mix_jitter: f32,
    /// Surface relief and gloss for the final lighting.
    pub relief: (f32, f32),
}

impl Style {
    /// Caspar David Friedrich (1774–1840), Dresden practice around 1820.
    /// Sources: notes/research/friedrich_materials.md.
    ///
    /// - Fine handwoven plain linen bought ready primed [KÖR p.283];
    ///   10–16 threads/cm (proxy, Eckersberg's Dresden canvases [CATS-E]).
    /// - Dresden grounds: 2–4 thin layers; lower ocher / red earth / chalk
    ///   layers "only served to smooth and even out the weave"; the top layer
    ///   brushed, its striations showing through the thin paint [KÖR p.284].
    ///   *Two Men Contemplating the Moon* has a reddish-ocher top ground used
    ///   as the mid-tone [KÖR p.284]. Ground total ~150–300 µm (proxy).
    /// - One or two very thin paint layers over a thin underpainting; skies,
    ///   mist and far hills stippled; paint pools in the ground texture
    ///   [CATS p.127; NG p.56].
    pub fn friedrich() -> Self {
        Style {
            name: "Caspar David Friedrich",
            width_mm: 440.0,
            linen: Linen { warp_per_cm: 15.0, weft_per_cm: 13.0, ..Linen::fine(1) },
            raw: hex("#a8966f"),
            ground: vec![
                Ground { color: hex("#9a5a36"), hiding: 0.8, um: 110.0, stiff: 0.25, apply: Apply::Knife { texture: 0.35 } },
                Ground { color: hex("#b08457"), hiding: 0.8, um: 70.0, stiff: 0.3, apply: Apply::Knife { texture: 0.3 } },
                Ground { color: hex("#a9785a"), hiding: 0.8, um: 60.0, stiff: 0.35, apply: Apply::Brush },
            ],
            broad: Tool { lay: 0.55, push: 0.03, ragged: 0.4, ..Tool::filbert(22.0) },
            body: Tool { lay: 0.7, push: 0.06, ..Tool::filbert(9.0) },
            detail: Tool::round_sable(2.2),
            line: Tool::rigger(0.6),
            blender: Some(Tool { pickup: 0.15, run: 45.0, ..Tool::badger(40.0) }),
            blend_passes: 3,
            blend_pressure: 0.5,
            palette: Palette::friedrich_1820(),
            body_medium: 0.2,
            thin_medium: 0.45,
            mix_jitter: 0.06,
            relief: (0.2, 0.02),
        }
    }

    /// Friedrich's early Berlin grounds (*Monk by the Sea*, *Abbey in the
    /// Oakwood*): bright red, then two light brown layers, the first two put
    /// on with a spatula, the third looking rolled on, with a finely
    /// textured structure he exploited [CATS p.127].
    pub fn friedrich_early() -> Self {
        Style {
            width_mm: 1714.0,
            linen: Linen { warp_per_cm: 12.0, weft_per_cm: 11.0, ..Linen::fine(1) },
            ground: vec![
                Ground { color: hex("#b0583a"), hiding: 0.85, um: 110.0, stiff: 0.25, apply: Apply::Knife { texture: 0.35 } },
                Ground { color: hex("#c9ad8a"), hiding: 0.8, um: 70.0, stiff: 0.3, apply: Apply::Knife { texture: 0.3 } },
                Ground { color: hex("#d8c7ab"), hiding: 0.8, um: 30.0, stiff: 0.5, apply: Apply::Roller },
            ],
            palette: Palette::friedrich_early(),
            ..Self::friedrich()
        }
    }

    /// A primed canvas as this painter bought or made it: linen of the
    /// painter's usual kind and physical size, and the ground layers.
    pub fn prepare(&self, width_px: usize, aspect: f32, seed: u64) -> Canvas {
        let mut c = Canvas::new(width_px, aspect, self.raw)
            .with_size_mm(self.width_mm)
            .with_linen(Linen { seed, ..self.linen });
        for (k, g) in self.ground.iter().enumerate() {
            if g.um <= 0.0 {
                continue;
            }
            let s = seed * 31 + k as u64;
            match g.apply {
                Apply::Knife { texture } => c.prime(g.color, g.hiding, g.um, g.stiff, texture, s),
                Apply::Roller => c.prime(g.color, g.hiding, g.um, g.stiff, 0.8, s),
                Apply::Brush => {
                    // a broad hog brush dragged across in long horizontal
                    // strokes; stiff paste keeps the bristle marks
                    let all = Mask::from_fn(c.f, |_, _| 1.0);
                    let hog = Tool { lay: 1.2, ragged: 0.2, ..Tool::hog_flat(40.0) };
                    let col = g.color;
                    let h = Handling::new(hog)
                        .color(move |_, _| col)
                        .paint(g.hiding, g.stiff)
                        .angle(|_, _| 0.0)
                        .angle_jitter(0.02)
                        .length(250.0, 600.0)
                        .coverage(3.5)
                        .pressure(0.8, 0.95)
                        .dips(1, (g.um / BRUSHED_UM_PER_LOAD).min(1.0), 0.3)
                        .jitter(0.004, 0.002)
                        .shake(0.15);
                    c.work(&all, &h, s);
                    c.dry();
                }
            }
        }
        c
    }

    /// Broad atmospheric passage (sky, fog, sea): long soft strokes, thin paint.
    pub fn broad(&self) -> Handling<'_> {
        Handling::new(self.broad.clone())
            .length(80.0, 220.0)
            .coverage(2.5)
            .mixed(&self.palette, self.thin_medium)
            .mix_jitter(self.mix_jitter)
            .pressure(0.55, 0.8)
            .dips(2, 0.4, 0.5)
            .angle_jitter(0.03)
            .ramps(0.12, 0.4)
    }

    /// Building a form in body color.
    pub fn body(&self) -> Handling<'_> {
        Handling::new(self.body.clone())
            .length(20.0, 60.0)
            .coverage(2.5)
            .mixed(&self.palette, self.body_medium)
            .mix_jitter(self.mix_jitter * 1.4)
            .pressure(0.6, 0.9)
            .dips(2, 0.56, 0.6)
    }

    /// Small forms and edges, cut in precisely.
    pub fn detail(&self) -> Handling<'_> {
        Handling::new(self.detail.clone())
            .length(4.0, 14.0)
            .coverage(3.0)
            .mixed(&self.palette, 0.1)
            .mix_jitter(self.mix_jitter)
            .pressure(0.7, 0.95)
            .dips(3, 0.9 * 0.8, 0.8)
            .clip(true)
            .threshold(0.1)
    }

    /// A glaze or thin scumble brushed over dry paint: a soft brush, paint
    /// that is mostly medium (`medium` ≈ 0.85–0.95 for a transparent glaze,
    /// ≈ 0.6 for a veiling scumble), laid thinly in long strokes. Vary the
    /// depth with `load_at`; fuse it afterwards with `blend()`.
    pub fn glaze(&self, medium: f32) -> Handling<'_> {
        let soft = Tool { stiffness: 0.3, lay: 0.8, pickup: 0.08, ragged: 0.2, ..Tool::filbert(self.broad.width * 1.2) };
        Handling::new(soft)
            .mixed(&self.palette, medium)
            .mix_jitter(self.mix_jitter * 0.5)
            .length(120.0, 300.0)
            .coverage(2.5)
            .pressure(0.5, 0.7)
            .dips(2, 0.35, 0.5)
            .angle_jitter(0.03)
            .ramps(0.2, 0.4)
    }

    /// Clean soft blender passes over a wet passage.
    pub fn blend(&self) -> Option<Handling<'_>> {
        let t = self.blender.clone()?;
        Some(
            Handling::new(t)
                .length(120.0, 300.0)
                .coverage(3.0)
                .pressure(self.blend_pressure * 0.8, self.blend_pressure)
                .dips(3, 0.0, 0.9)
                .blender()
                .angle_jitter(0.02),
        )
    }

    /// A brush held for lines.
    pub fn line_tool(&self, width: f32) -> Tool {
        Tool { width, length: width * 5.0, ..self.line.clone() }
    }

    /// Scumbling handling (not Friedrich's habit, for painters who use it).
    pub fn scumble(&self) -> Handling<'_> {
        Handling::new(self.body.clone()).scrub(3).mixed(&self.palette, 0.5).length(10.0, 20.0).orient(Orient::Across)
    }
}
//! The painter's palette: a few tube paints, and mixing on the palette.
//!
//! A painting asks for a color; the painter can only mix it from the tubes
//! they own. `Palette::mix` searches mixtures of up to three tube paints (in
//! proportions a painter would knife together) for the one that looks
//! closest (OKLab distance), mixing the way pigments mix (Mixbox latent
//! space, weighted by each paint's tinting strength). Colors the palette
//! cannot reach come out as the nearest color the painter could actually
//! make: the palette limits the gamut, as it did for the painter.
//!
//! Masstone colors, hiding and tinting strength are approximations from
//! pigment knowledge (not measurements); which pigments a painter owned is
//! sourced per palette.

use crate::color::{Rgb, hex, to_oklab};
use crate::rng::Rng;
use crate::wet::Paint;
use std::collections::HashMap;
use std::sync::Mutex;

/// A tube (or hand-ground) paint.
#[derive(Clone, Debug)]
pub struct Tube {
    pub name: &'static str,
    /// Masstone color, linear RGB.
    pub color: Rgb,
    /// Hiding power (0 transparent .. 1 opaque).
    pub hiding: f32,
    /// Stiffness straight from the tube (0 fluid .. 1 stiff).
    pub stiff: f32,
    /// Tinting strength relative to an average pigment (smalt is weak,
    /// Prussian blue very strong).
    pub strength: f32,
}

fn tube(name: &'static str, color: &str, hiding: f32, stiff: f32, strength: f32) -> Tube {
    Tube { name, color: hex(color), hiding, stiff, strength }
}

/// A mixture on the palette: parts of tubes.
#[derive(Clone, Debug)]
pub struct Mixture {
    /// (tube index, fraction by volume), fractions sum to 1.
    pub parts: Vec<(usize, f32)>,
    pub color: Rgb,
    pub hiding: f32,
    pub stiff: f32,
    /// OKLab distance from the color asked for.
    pub error: f32,
}

pub struct Palette {
    pub name: &'static str,
    pub tubes: Vec<Tube>,
    lat: Vec<[f32; mixbox::LATENT_SIZE]>,
    cache: Mutex<HashMap<[i32; 3], Mixture>>,
}

impl Clone for Palette {
    fn clone(&self) -> Self {
        Palette::new(self.name, self.tubes.clone())
    }
}

impl std::fmt::Debug for Palette {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Palette").field("name", &self.name).field("tubes", &self.tubes.iter().map(|t| t.name).collect::<Vec<_>>()).finish()
    }
}

impl Palette {
    pub fn new(name: &'static str, tubes: Vec<Tube>) -> Self {
        let lat = tubes.iter().map(|t| mixbox::linear_float_rgb_to_latent(&t.color)).collect();
        Palette { name, tubes, lat, cache: Mutex::new(HashMap::new()) }
    }

    /// Friedrich before ~1820: lead white, smalt (semi-transparent cobalt
    /// glass, weak, in several grades), ochres and earths, vermilion, umber,
    /// bone black (notes/research/friedrich_materials.md §4: CATS p.127,
    /// NG pp.51–56, ALF p.348). Naples yellow and Prussian blue are uncertain
    /// and left out.
    pub fn friedrich_early() -> Self {
        Palette::new(
            "Friedrich, early",
            vec![
                tube("lead white", "#efe9dc", 0.82, 0.8, 1.0),
                tube("smalt", "#5a6e9e", 0.3, 0.55, 0.45),
                tube("pale smalt", "#8d9bb8", 0.35, 0.55, 0.35),
                tube("yellow ochre", "#b98a36", 0.8, 0.7, 0.8),
                tube("red earth", "#9c4a30", 0.85, 0.7, 0.9),
                tube("vermilion", "#cf3a24", 0.9, 0.75, 1.0),
                tube("raw umber", "#5c4c3a", 0.8, 0.65, 0.9),
                tube("bone black", "#1e1b19", 0.9, 0.7, 1.1),
            ],
        )
    }

    /// Friedrich from ~1820: cobalt blue and chrome yellow join the palette
    /// and largely replace smalt (ALF pp.341, 348–349; NG p.56).
    pub fn friedrich_1820() -> Self {
        let mut t = Palette::friedrich_early().tubes;
        t.retain(|t| t.name != "smalt");
        t.push(tube("cobalt blue", "#2f55a8", 0.55, 0.6, 0.8));
        t.push(tube("chrome yellow", "#e8b21c", 0.9, 0.7, 1.0));
        Palette::new("Friedrich, after 1820", t)
    }

    fn eval(&self, parts: &[(usize, f32)]) -> (Rgb, f32, f32) {
        let mut lat = [0.0f32; mixbox::LATENT_SIZE];
        let (mut wsum, mut hid, mut stf) = (0.0, 0.0, 0.0);
        for &(i, f) in parts {
            let w = f * self.tubes[i].strength;
            for k in 0..mixbox::LATENT_SIZE {
                lat[k] += self.lat[i][k] * w;
            }
            wsum += w;
            hid += self.tubes[i].hiding * f;
            stf += self.tubes[i].stiff * f;
        }
        for v in lat.iter_mut() {
            *v /= wsum.max(1e-9);
        }
        (mixbox::latent_to_linear_float_rgb(&lat), hid, stf)
    }

    fn mixture(&self, parts: Vec<(usize, f32)>, target_lab: Rgb) -> Mixture {
        let (color, hiding, stiff) = self.eval(&parts);
        Mixture { error: dist(to_oklab(color), target_lab), parts, color, hiding, stiff }
    }

    /// The closest mixture of up to three tubes to `target` (linear RGB).
    pub fn mix(&self, target: Rgb) -> Mixture {
        let lab = to_oklab(target);
        let key = [(lab[0] * 400.0) as i32, (lab[1] * 400.0) as i32, (lab[2] * 400.0) as i32];
        if let Some(m) = self.cache.lock().unwrap().get(&key) {
            return m.clone();
        }
        let m = self.search(lab);
        self.cache.lock().unwrap().insert(key, m.clone());
        m
    }

    fn search(&self, lab: Rgb) -> Mixture {
        let n = self.tubes.len();
        let score = |parts: &[(usize, f32)]| dist(to_oklab(self.eval(parts).0), lab);
        // coarse: every pair and triple on a grid of twelfths
        let g = 12;
        let mut best: (f32, Vec<(usize, f32)>) = (f32::MAX, vec![]);
        for i in 0..n {
            let p = vec![(i, 1.0)];
            let s = score(&p);
            if s < best.0 {
                best = (s, p);
            }
            for j in i + 1..n {
                for a in 1..g {
                    let p = vec![(i, a as f32 / g as f32), (j, 1.0 - a as f32 / g as f32)];
                    let s = score(&p);
                    if s < best.0 {
                        best = (s, p);
                    }
                }
                for k in j + 1..n {
                    for a in 1..g {
                        for b in 1..g - a {
                            let (fa, fb) = (a as f32 / g as f32, b as f32 / g as f32);
                            let p = vec![(i, fa), (j, fb), (k, 1.0 - fa - fb)];
                            let s = score(&p);
                            if s < best.0 {
                                best = (s, p);
                            }
                        }
                    }
                }
            }
        }
        // refine the proportions by coordinate descent with shrinking steps
        let mut parts = best.1;
        let mut s0 = best.0;
        let mut step = 1.0 / g as f32;
        while step > 1e-3 && parts.len() > 1 {
            let mut improved = false;
            for a in 0..parts.len() {
                for b in 0..parts.len() {
                    if a == b || parts[b].1 < step {
                        continue;
                    }
                    let mut q = parts.clone();
                    q[a].1 += step;
                    q[b].1 -= step;
                    let s = score(&q);
                    if s < s0 {
                        s0 = s;
                        parts = q;
                        improved = true;
                    }
                }
            }
            if !improved {
                step *= 0.5;
            }
        }
        parts.retain(|p| p.1 > 1e-4);
        self.mixture(parts, lab)
    }

    /// The painter never mixes the same pile twice: jitter the proportions
    /// (relative sd `amount`) and remix.
    pub fn remix(&self, m: &Mixture, amount: f32, rng: &mut Rng) -> Mixture {
        if amount <= 0.0 || m.parts.len() < 2 {
            return m.clone();
        }
        let mut parts: Vec<(usize, f32)> = m.parts.iter().map(|&(i, f)| (i, (f * (1.0 + rng.normal() * amount)).max(0.0))).collect();
        let s: f32 = parts.iter().map(|p| p.1).sum();
        parts.iter_mut().for_each(|p| p.1 /= s.max(1e-9));
        let (color, hiding, stiff) = self.eval(&parts);
        Mixture { parts, color, hiding, stiff, error: m.error }
    }

    /// A paint mixed to `target`, thinned: `medium` 0..1 is the fraction of
    /// oil medium added (it lowers hiding and stiffness).
    pub fn paint(&self, target: Rgb, medium: f32) -> Paint {
        let m = self.mix(target);
        m.paint(medium)
    }

    /// Human-readable recipe, e.g. "lead white 0.72 + yellow ochre 0.20 + raw umber 0.08".
    pub fn recipe(&self, m: &Mixture) -> String {
        m.parts.iter().map(|&(i, f)| format!("{} {:.2}", self.tubes[i].name, f)).collect::<Vec<_>>().join(" + ")
    }
}

impl Mixture {
    /// This mixture as paint on the brush, thinned with `medium` (0..1).
    pub fn paint(&self, medium: f32) -> Paint {
        let k = (1.0 - medium).clamp(0.0, 1.0);
        // medium dilutes the pigment (less hiding per unit thickness) and makes
        // the paint flow (stiffness falls faster than hiding)
        Paint { color: self.color, hiding: (self.hiding * k.powf(0.6)).clamp(0.02, 0.99), stiff: self.stiff * k * k }
    }
}

fn dist(a: Rgb, b: Rgb) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

//! Working an area with a real (simulated) brush.
//!
//! `Handling` describes how a painter works a region: which tool, how long
//! the strokes are and which way they run, how hard they press, how often
//! they go back to the palette and whether they wipe the brush first.
//! `Canvas::work` then drives a `Held` brush over the region stroke by
//! stroke, so all mixing, smearing, dry-brush and ridges come from the
//! bristle simulation, not from blend modes.

use crate::bristle::{Gesture, Held, Orient, Rect, Tool, footprint};
use crate::canvas::Canvas;
use crate::color::{Rgb, from_oklab, to_oklab};
use crate::mask::Mask;
use crate::palette::Palette;
use crate::rng::Rng;
use crate::wet::Paint;
use rayon::prelude::*;

type Field<'a, T> = Box<dyn Fn(f32, f32) -> T + Sync + 'a>;

pub struct Handling<'a> {
    pub tool: Tool,
    /// Stroke length range in units.
    pub length: (f32, f32),
    /// How many layers of strokes cover each point on average.
    pub coverage: f32,
    /// Stroke direction field (radians, 0 = left→right).
    pub angle: Field<'a, f32>,
    pub angle_jitter: f32,
    /// Color mixed on the palette for a stroke centered at a point.
    pub color: Field<'a, Rgb>,
    /// Palette-mixing inconsistency per dip: OKLab L and a/b sd.
    pub jitter: (f32, f32),
    /// Hiding and stiffness of the paint when it isn't mixed from a
    /// palette (see `Paint`).
    pub hiding: f32,
    pub stiff: f32,
    /// Mix each pile from these tube paints, thinned with this fraction of
    /// oil medium (0..1). The color field is then what the painter aims for.
    pub palette: Option<(&'a Palette, f32)>,
    /// How unevenly each pile is mixed: relative sd of the proportions.
    pub mix_jitter: f32,
    /// Where the painter loads the brush more or less (multiplies `load`,
    /// evaluated at each stroke's center): a glaze goes on deeper where the
    /// brush carries more.
    pub load_at: Option<Field<'a, f32>>,
    /// Pressure range (a random value in it per stroke).
    pub pressure: (f32, f32),
    pub orient: Orient,
    /// Strokes between trips to the palette.
    pub dip_every: usize,
    /// How much of a full load a dip takes.
    pub load: f32,
    /// Fraction of old paint wiped off before each dip (1 = clean, 0 = dirty).
    pub wipe: f32,
    /// Clean blender: never loads paint, wiped every `dip_every` strokes.
    pub blender: bool,
    /// Scumble: short back-and-forth strokes instead of single pulls.
    pub scrub: usize,
    /// Clip bristle contact to the mask (crisp, cut-in edges).
    pub clip: bool,
    /// Minimum mask value for a stroke center.
    pub threshold: f32,
    /// Press-down and lift-off fractions of each stroke.
    pub ramps: (f32, f32),
    /// Hand unsteadiness (1 = normal).
    pub shake: f32,
}

impl<'a> Handling<'a> {
    pub fn new(tool: Tool) -> Self {
        Handling {
            tool,
            length: (30.0, 90.0),
            coverage: 2.0,
            angle: Box::new(|_, _| 0.0),
            angle_jitter: 0.08,
            color: Box::new(|_, _| [0.5; 3]),
            jitter: (0.02, 0.006),
            hiding: 0.85,
            stiff: 0.8,
            pressure: (0.6, 0.9),
            orient: Orient::Across,
            dip_every: 1,
            load: 0.8 * 0.8,
            wipe: 0.6,
            blender: false,
            scrub: 0,
            clip: false,
            threshold: 0.3,
            ramps: (0.08, 0.15),
            shake: 1.0,
            palette: None,
            mix_jitter: 0.08,
            load_at: None,
        }
    }
    pub fn length(mut self, a: f32, b: f32) -> Self {
        self.length = (a, b);
        self
    }
    pub fn coverage(mut self, c: f32) -> Self {
        self.coverage = c;
        self
    }
    pub fn angle(mut self, f: impl Fn(f32, f32) -> f32 + Sync + 'a) -> Self {
        self.angle = Box::new(f);
        self
    }
    pub fn angle_jitter(mut self, a: f32) -> Self {
        self.angle_jitter = a;
        self
    }
    pub fn color(mut self, f: impl Fn(f32, f32) -> Rgb + Sync + 'a) -> Self {
        self.color = Box::new(f);
        self
    }
    pub fn jitter(mut self, l: f32, hue: f32) -> Self {
        self.jitter = (l, hue);
        self
    }
    /// A fixed paint (no palette mixing).
    pub fn paint(mut self, hiding: f32, stiff: f32) -> Self {
        self.hiding = hiding;
        self.stiff = stiff;
        self.palette = None;
        self
    }
    /// Mix every pile from `palette`'s tubes, thinned with `medium` (0..1).
    pub fn mixed(mut self, palette: &'a Palette, medium: f32) -> Self {
        self.palette = Some((palette, medium));
        self
    }
    /// Change how much medium goes into the palette mixtures.
    pub fn medium(mut self, medium: f32) -> Self {
        let (p, _) = self.palette.expect("medium() needs a palette: use mixed()");
        self.palette = Some((p, medium));
        self
    }
    /// Vary the load across the canvas (see `load_at`).
    pub fn load_at(mut self, f: impl Fn(f32, f32) -> f32 + Sync + 'a) -> Self {
        self.load_at = Some(Box::new(f));
        self
    }
    pub fn mix_jitter(mut self, sd: f32) -> Self {
        self.mix_jitter = sd;
        self
    }
    /// How much paint each trip to the palette puts on the brush (0..1 of full).
    pub fn load(mut self, amount: f32) -> Self {
        self.load = amount;
        self
    }
    pub fn pressure(mut self, a: f32, b: f32) -> Self {
        self.pressure = (a, b);
        self
    }
    pub fn orient(mut self, o: Orient) -> Self {
        self.orient = o;
        self
    }
    pub fn dips(mut self, every: usize, load: f32, wipe: f32) -> Self {
        self.dip_every = every.max(1);
        self.load = load;
        self.wipe = wipe;
        self
    }
    pub fn blender(mut self) -> Self {
        self.blender = true;
        self
    }
    pub fn scrub(mut self, n: usize) -> Self {
        self.scrub = n;
        self
    }
    pub fn clip(mut self, on: bool) -> Self {
        self.clip = on;
        self
    }
    pub fn threshold(mut self, t: f32) -> Self {
        self.threshold = t;
        self
    }
    pub fn ramps(mut self, attack: f32, release: f32) -> Self {
        self.ramps = (attack, release);
        self
    }
    pub fn shake(mut self, k: f32) -> Self {
        self.shake = k;
        self
    }
}

/// One planned stroke.
struct Plan {
    pts: Vec<(f32, f32)>,
    pressure: f32,
    fade: f32,
    /// Paint to dip into before this stroke (None = no trip to the palette).
    dip: Option<Paint>,
    /// How much of a full load that dip takes.
    load: f32,
}

impl Canvas {
    /// Work the region `mask` with a simulated brush, stroke by stroke.
    ///
    /// Strokes are planned up front, then grouped into square passages
    /// (tiles) larger than twice any stroke's reach. Passages in a 2×2
    /// checkerboard phase can't share a pixel, so each gets its own brush and
    /// they are painted in parallel; phases run one after another.
    pub fn work(&mut self, mask: &Mask, hd: &Handling, seed: u64) {
        self.check_mask(mask);
        let mut rng = Rng::new(seed);
        let f = self.f;
        let mean_len = 0.5 * (hd.length.0 + hd.length.1);
        // one stroke per gap² of area gives coverage = width · length / gap²
        let gap = (hd.tool.width * mean_len.max(hd.tool.width) / hd.coverage.max(0.05)).sqrt().max(0.5);
        let (cols, rows) = ((f.width() / gap).ceil() as usize + 1, (f.height() / gap).ceil() as usize + 1);
        let mut centers = Vec::new();
        for j in 0..rows {
            for i in 0..cols {
                let x = (i as f32 + rng.f()) * gap;
                let y = (j as f32 + rng.f()) * gap;
                if x > f.width() || y > f.height() {
                    continue;
                }
                if mask.data[f.index(x, y)] >= hd.threshold {
                    centers.push((x, y));
                }
            }
        }
        for i in (1..centers.len()).rev() {
            let j = (rng.next_u64() % (i as u64 + 1)) as usize;
            centers.swap(i, j);
        }
        if centers.is_empty() {
            return;
        }

        // plan every stroke deterministically
        let mut plans = Vec::with_capacity(centers.len());
        // how far (units) any stroke's pixel footprint reaches from its center
        let (mut ex, mut ey) = (0.0f32, 0.0f32);
        for &(cx, cy) in &centers {
            let len = rng.range(hd.length.0, hd.length.1);
            let bend = rng.normal() * hd.angle_jitter;
            let pts: Vec<(f32, f32)> = if hd.scrub > 0 {
                let a = (hd.angle)(cx, cy) + bend;
                let (ca, sa) = (a.cos(), a.sin());
                let (nx, ny) = (-sa, ca);
                let amp = len * 0.5;
                let adv = hd.tool.width * 0.35;
                (0..=hd.scrub * 2)
                    .map(|k| {
                        let s = if k % 2 == 0 { -amp } else { amp };
                        let t = (k as f32 - hd.scrub as f32) * adv * 0.5;
                        (cx + ca * s + nx * t + rng.normal() * 1.5, cy + sa * s + ny * t + rng.normal() * 1.5)
                    })
                    .collect()
            } else {
                trace(&*hd.angle, cx, cy, len, bend, &mut rng)
            };
            let rect = footprint(&hd.tool, &pts, hd.shake, f.scale, f.w, f.h);
            if let Some(r) = rect {
                let (px, py) = (cx * f.scale, cy * f.scale);
                ex = ex.max((px - r.0 as f32).max(r.2 as f32 - px) / f.scale);
                ey = ey.max((py - r.1 as f32).max(r.3 as f32 - py) / f.scale);
            }
            let pressure = rng.range(hd.pressure.0, hd.pressure.1);
            let fade = rng.range(0.75, 1.05);
            let target = (hd.color)(cx, cy);
            let paint = match hd.palette {
                // on the palette: mix the pile from tubes, never twice alike
                Some((pal, medium)) => pal.remix(&pal.mix(target), hd.mix_jitter, &mut rng).paint(medium),
                None => {
                    let lab = to_oklab(target);
                    let col = from_oklab([
                        lab[0] + rng.normal() * hd.jitter.0,
                        lab[1] + rng.normal() * hd.jitter.1,
                        lab[2] + rng.normal() * hd.jitter.1,
                    ]);
                    Paint { color: col, hiding: hd.hiding, stiff: hd.stiff }
                }
            };
            let load = hd.load * hd.load_at.as_ref().map_or(1.0, |f| f(cx, cy).max(0.0));
            plans.push((cx, cy, rect, Plan { pts, pressure, fade, dip: Some(paint), load }));
        }
        // tiles are sized per axis from the footprints: tiles painted at the
        // same time are one tile apart, so a tile at least twice the largest
        // reach keeps their pixels disjoint (long horizontal strokes get wide,
        // short tiles)
        let margin = 2.0 / f.scale;
        let (tile_x, tile_y) = ((2.0 * ex + margin).max(gap * 2.0), (2.0 * ey + margin).max(gap * 2.0));
        let (tw, th) = ((f.width() / tile_x).ceil().max(1.0) as usize, (f.height() / tile_y).ceil().max(1.0) as usize);
        if std::env::var_os("PAINT_DEBUG").is_some() {
            eprintln!("work: {} strokes, reach {ex:.0}x{ey:.0}, tiles {tw}x{th}", centers.len());
        }
        let mut tiles: Vec<Vec<Plan>> = (0..tw * th).map(|_| Vec::new()).collect();
        // pixel footprint of each tile: the union of its strokes'
        let mut tile_rect: Vec<Option<Rect>> = vec![None; tw * th];
        for (cx, cy, rect, p) in plans {
            let tx = ((cx / tile_x) as usize).min(tw - 1);
            let ty = ((cy / tile_y) as usize).min(th - 1);
            let t = ty * tw + tx;
            if let Some(r) = rect {
                tile_rect[t] = Some(match tile_rect[t] {
                    None => r,
                    Some(a) => (a.0.min(r.0), a.1.min(r.1), a.2.max(r.2), a.3.max(r.3)),
                });
                tiles[t].push(p);
            }
        }
        // trips to the palette: every `dip_every` strokes within a passage
        for t in tiles.iter_mut() {
            for (k, p) in t.iter_mut().enumerate() {
                if k % hd.dip_every != 0 {
                    p.dip = None;
                }
            }
        }
        let n_strokes: usize = tiles.iter().map(|t| t.len()).sum();
        let first_id = self.next_stroke_ids(n_strokes as u32);
        let mut offsets = Vec::with_capacity(tiles.len());
        let mut acc = 0u32;
        for t in &tiles {
            offsets.push(acc);
            acc += t.len() as u32;
        }

        let surf = self.surf();
        let clip = if hd.clip { Some(mask) } else { None };
        let mut phases = [(0usize, 0usize), (1, 0), (0, 1), (1, 1)];
        for i in (1..4).rev() {
            let j = (rng.next_u64() % (i as u64 + 1)) as usize;
            phases.swap(i, j);
        }
        let mut dirty: crate::bristle::Bounds = None;
        for (px, py) in phases {
            let idx: Vec<usize> = (0..tiles.len()).filter(|&i| (i % tw) % 2 == px && (i / tw) % 2 == py && tile_rect[i].is_some()).collect();
            let batches = disjoint_batches(&idx, &tile_rect);
            if std::env::var_os("PAINT_DEBUG").is_some() {
                eprintln!("  phase: {} tiles in {} batches", idx.len(), batches.len());
            }
            for batch in batches {
                let results: Vec<crate::bristle::Bounds> = batch
                    .par_iter()
                    .map(|&ti| {
                        let mut held = Held::new(hd.tool.clone(), seed ^ 0x5EED ^ (ti as u64).wrapping_mul(0x9E37_79B9));
                        let mut scratch = Vec::new();
                        let mut b: crate::bristle::Bounds = None;
                        for (k, p) in tiles[ti].iter().enumerate() {
                            if let Some(paint) = p.dip {
                                if hd.blender {
                                    held.wipe(0.9);
                                } else {
                                    held.wipe(hd.wipe);
                                    held.load(paint, p.load);
                                }
                            }
                            let g = Gesture::new(p.pts.clone())
                                .pressure(p.pressure, p.pressure * p.fade)
                                .orient(hd.orient)
                                .ramps(hd.ramps.0, hd.ramps.1)
                                .shake(hd.shake);
                            let id = first_id.wrapping_add(offsets[ti] + k as u32);
                            // SAFETY: every pixel this drag touches lies in its
                            // stroke footprint, inside this tile's rect; tiles in
                            // one batch have disjoint rects; `surf()` checked the
                            // buffers match the frame.
                            let r = unsafe { crate::bristle::drag_on(surf, &mut held, &g, clip, id, &mut scratch) };
                            if let Some((a, c, d, e)) = r {
                                b = Some(match b {
                                    None => (a, c, d, e),
                                    Some((a0, c0, d0, e0)) => (a0.min(a), c0.min(c), d0.max(d), e0.max(e)),
                                });
                            }
                        }
                        b
                    })
                    .collect();
                for r in results.into_iter().flatten() {
                    dirty = Some(match dirty {
                        None => r,
                        Some((a0, c0, d0, e0)) => (a0.min(r.0), c0.min(r.1), d0.max(r.2), e0.max(r.3)),
                    });
                }
            }
        }
        if let Some((x0, y0, x1, y1)) = dirty {
            self.wet.touch(x0, y0, x1, y1);
        }
    }
}

/// Group tiles (in the given, deterministic order) into batches whose
/// footprints are pairwise disjoint; tiles in a batch may run concurrently.
fn disjoint_batches(idx: &[usize], rects: &[Option<Rect>]) -> Vec<Vec<usize>> {
    let overlaps = |a: Rect, b: Rect| a.0 < b.2 && b.0 < a.2 && a.1 < b.3 && b.1 < a.3;
    let mut batches: Vec<(Vec<usize>, Vec<Rect>)> = Vec::new();
    for &ti in idx {
        let r = rects[ti].expect("tile without footprint");
        match batches.iter_mut().find(|(_, rs)| rs.iter().all(|&q| !overlaps(q, r))) {
            Some((ts, rs)) => {
                ts.push(ti);
                rs.push(r);
            }
            None => batches.push((vec![ti], vec![r])),
        }
    }
    batches.into_iter().map(|(ts, _)| ts).collect()
}

/// A streamline through (cx, cy) along the angle field, random direction.
fn trace(angle: &(dyn Fn(f32, f32) -> f32 + Sync), cx: f32, cy: f32, len: f32, bend: f32, rng: &mut Rng) -> Vec<(f32, f32)> {
    let steps = 3;
    let h = len / (2 * steps) as f32;
    let mut fwd = vec![(cx, cy)];
    let mut back = vec![];
    let (mut x, mut y) = (cx, cy);
    for k in 0..steps {
        let a = angle(x, y) + bend * (1.0 + k as f32 * 0.3);
        x += a.cos() * h;
        y += a.sin() * h;
        fwd.push((x, y));
    }
    let (mut x, mut y) = (cx, cy);
    for k in 0..steps {
        let a = angle(x, y) + bend * (1.0 + k as f32 * 0.3);
        x -= a.cos() * h;
        y -= a.sin() * h;
        back.push((x, y));
    }
    back.reverse();
    back.extend(fwd);
    if rng.chance(0.5) {
        back.reverse();
    }
    back
}
//! A painter's hand working at one spot: a local frame (origin, scale, and
//! "up") so a small motif can be written as a list of brush gestures in its
//! own coordinates. It knows nothing about what is painted; figures and other
//! motifs are written stroke by stroke in the paintings themselves.

use crate::bristle::{Gesture, Held, Orient, Tool};
use crate::canvas::Canvas;
use crate::mask::Mask;
use crate::rng::Rng;
use crate::wet::Paint;

pub struct Hand {
    /// Origin in canvas units (e.g. between a figure's feet).
    pub at: (f32, f32),
    /// Canvas units per local unit (e.g. a figure's height).
    pub size: f32,
    /// Tremor: random offset of each control point, in local units.
    pub tremor: f32,
    pub rng: Rng,
}

/// One gesture in local coordinates: `u` across (+ right), `v` up.
pub struct Mark<'a> {
    pub pts: &'a [(f32, f32)],
    /// Pressure at start and end.
    pub pressure: (f32, f32),
    /// Attack and release fractions.
    pub ramps: (f32, f32),
}

impl Hand {
    pub fn new(at: (f32, f32), size: f32, seed: u64) -> Self {
        Hand { at, size, tremor: 0.004, rng: Rng::new(seed) }
    }

    /// Local (u, v) to canvas units.
    pub fn p(&self, u: f32, v: f32) -> (f32, f32) {
        (self.at.0 + u * self.size, self.at.1 - v * self.size)
    }

    /// Pick up a brush of `width` local units, loaded with `paint`.
    pub fn take(&mut self, tool: fn(f32) -> Tool, width: f32, paint: Paint, load: f32) -> Held {
        let mut h = Held::new(tool(width * self.size), self.rng.next_u64());
        h.load(paint, load);
        h
    }

    /// Drag the held brush through local points.
    pub fn mark(&mut self, c: &mut Canvas, held: &mut Held, m: Mark, clip: Option<&Mask>) {
        let t = self.tremor;
        let pts: Vec<(f32, f32)> = m
            .pts
            .iter()
            .map(|&(u, v)| {
                let (du, dv) = (self.rng.normal() * t, self.rng.normal() * t);
                self.p(u + du, v + dv)
            })
            .collect();
        let g = Gesture::new(pts).pressure(m.pressure.0, m.pressure.1).ramps(m.ramps.0, m.ramps.1).orient(Orient::Across);
        c.drag(held, &g, clip);
    }

    /// Shorthand: a stroke with given pressures and default ramps.
    pub fn line(&mut self, c: &mut Canvas, held: &mut Held, pts: &[(f32, f32)], p0: f32, p1: f32) {
        self.mark(c, held, Mark { pts, pressure: (p0, p1), ramps: (0.1, 0.25) }, None);
    }

    /// A dab: a very short press at (u, v) in direction `dir` (radians, 0 = right, up positive).
    pub fn dab(&mut self, c: &mut Canvas, held: &mut Held, u: f32, v: f32, len: f32, dir: f32, p: f32) {
        let (du, dv) = (dir.cos() * len * 0.5, dir.sin() * len * 0.5);
        self.mark(c, held, Mark { pts: &[(u - du, v - dv), (u + du, v + dv)], pressure: (p, p), ramps: (0.0, 0.3) }, None);
    }
}

//! Friedrich's small figures, written as brush gestures.
//!
//! Local coordinates: `u` across (+ = the figure's right, which is also the
//! viewer's right since they face away), `v` up from the feet, both in figure
//! heights. Sources for what they look like:
//! - Monk by the Sea: "a single figure, dressed in a long garment ... turned
//!   almost completely away from the viewer"; "the long blond hair and round
//!   skull" (https://en.wikipedia.org/wiki/The_Monk_by_the_Sea).
//! - Two Men Contemplating the Moon: "The man on the right is wearing a
//!   grey-green cape and the black beret of the altdeutsche Tracht and has a
//!   stick in his right hand. The man on the left is somewhat higher on the
//!   path and is leaning on his companion's shoulder; he is slimmer and is
//!   wearing a grey-green frock-coat, from which a white collar protrudes, and
//!   the black cap of an early Burschenschaft"
//!   (https://en.wikipedia.org/wiki/Two_Men_Contemplating_the_Moon).

use paint::{Canvas, Hand, Mark, Paint, Rgb, Tool};
use std::f32::consts::FRAC_PI_2;

fn body(color: Rgb) -> Paint {
    Paint { color, hiding: 0.97, stiff: 1.0 }
}

/// Thin paint for small touches (heads, caps, collars): no impasto knobs.
fn thin(color: Rgb) -> Paint {
    Paint { color, hiding: 0.95, stiff: 0.45 }
}

fn lean(color: Rgb) -> Paint {
    Paint { color, hiding: 0.55, stiff: 0.4 }
}

/// The monk: long dark habit widening a little to the hem, sloping shoulders,
/// right arm raised with the hand to the face (the elbow shows at his side),
/// round head of pale hair. `light` is a lean rim touched on the lit side.
pub fn monk(c: &mut Canvas, at: (f32, f32), size: f32, robe: Rgb, hair: Rgb, light: Option<Rgb>, seed: u64) {
    let mut h = Hand::new(at, size, seed);
    let p = body(robe);
    let mut b = h.take(Tool::round_sable, 0.075, p, 1.0);
    // the habit: four long strokes from the shoulders down, pressing harder
    // toward the hem so it widens; outer strokes lean out a little
    for (i, (u0, u1)) in [(-0.045f32, -0.075f32), (0.045, 0.08), (-0.014, -0.025), (0.016, 0.028)].iter().enumerate() {
        if i % 2 == 0 {
            b.reload(p, 1.0);
        }
        let mid = (u0 + u1) * 0.5 + h.rng.normal() * 0.004;
        h.mark(c, &mut b, Mark { pts: &[(*u0, 0.82), (mid, 0.45), (*u1, 0.02)], pressure: (0.65, 1.0), ramps: (0.05, 0.06) }, None);
    }
    // and over it once more, lighter, to close the grooves between the hairs
    for (u0, u1) in [(-0.03f32, -0.05f32), (0.03, 0.055), (0.0, 0.0)] {
        b.reload(p, 1.0);
        h.mark(c, &mut b, Mark { pts: &[(u0, 0.8), (u1, 0.03)], pressure: (0.6, 0.85), ramps: (0.1, 0.1) }, None);
    }
    b.reload(p, 1.0);
    // shoulders: one stroke across, dropping at both ends
    h.line(c, &mut b, &[(-0.085, 0.76), (-0.04, 0.825), (0.04, 0.825), (0.085, 0.76)], 0.7, 0.7);
    // raised right arm: out to the elbow and back in toward the face
    h.line(c, &mut b, &[(0.06, 0.79), (0.115, 0.69), (0.085, 0.61)], 0.75, 0.55);
    // hem: firm across the bottom
    h.line(c, &mut b, &[(-0.095, 0.03), (0.0, 0.015), (0.105, 0.03)], 0.8, 0.8);
    // the hood gathered at the nape
    let mut nb = h.take(Tool::round_sable, 0.04, p, 0.8);
    h.dab(c, &mut nb, 0.0, 0.845, 0.03, 0.0, 0.8);
    // let the habit set before the head goes on, so the hair stays clean
    c.dry();
    // the head: a dab of pale hair
    let mut hb = h.take(Tool::round_sable, 0.068, thin(hair), 1.0 * 0.45);
    h.dab(c, &mut hb, 0.004, 0.9, 0.065, FRAC_PI_2, 1.0);
    if let Some(l) = light {
        // light from the left: a lean touch dragged down the left edge,
        // barely pressing, and one along the left shoulder
        c.dry();
        let tone = paint::color::mix(robe, l, 0.4, paint::Mix::Pigment);
        let mut lb = h.take(Tool::round_sable, 0.025, lean(tone), 0.4 * 0.4);
        h.mark(c, &mut lb, Mark { pts: &[(-0.07, 0.75), (-0.074, 0.6), (-0.078, 0.45)], pressure: (0.35, 0.15), ramps: (0.15, 0.6) }, None);
        h.mark(c, &mut lb, Mark { pts: &[(-0.02, 0.83), (-0.06, 0.8)], pressure: (0.4, 0.3), ramps: (0.1, 0.4) }, None);
        h.dab(c, &mut lb, -0.02, 0.91, 0.03, FRAC_PI_2, 0.4);
    }
}

/// Trousers and boots, painted first so the coat can come down over them.
fn legs(c: &mut Canvas, h: &mut Hand, trousers: Rgb, dark: Rgb, gap: f32, w: f32) {
    let tr = body(trousers);
    let mut b = h.take(Tool::round_sable, w, tr, 1.0);
    for s in [-1.0f32, 1.0] {
        h.mark(c, &mut b, Mark { pts: &[(s * gap, 0.45), (s * gap, 0.2), (s * (gap + 0.002), 0.035)], pressure: (0.95, 0.65), ramps: (0.0, 0.05) }, None);
    }
    let mut bt = h.take(Tool::round_sable, w * 0.62, thin(dark), 1.0 * 0.45);
    for s in [-1.0f32, 1.0] {
        h.mark(c, &mut bt, Mark { pts: &[(s * (gap - 0.004), 0.02), (s * (gap + 0.024), 0.012)], pressure: (0.9, 0.6), ramps: (0.0, 0.3) }, None);
    }
    c.dry();
}

/// The older man in a cape and beret, stick in his right hand. Returns his
/// left shoulder in canvas units (for a companion's hand).
#[allow(clippy::too_many_arguments)]
pub fn man_in_cape(c: &mut Canvas, at: (f32, f32), size: f32, cape: Rgb, dark: Rgb, hair: Rgb, rim: Option<Rgb>, seed: u64) -> (f32, f32) {
    let mut h = Hand::new(at, size, seed);
    // back to front: legs, the stick, then the cape over them
    legs(c, &mut h, paint::color::mix(dark, cape, 0.3, paint::Mix::Pigment), dark, 0.03, 0.045);
    let mut st = h.take(Tool::rigger, 0.012, body(dark), 1.0);
    h.mark(c, &mut st, Mark { pts: &[(0.15, 0.52), (0.175, 0.26), (0.2, 0.0)], pressure: (0.9, 0.8), ramps: (0.0, 0.05) }, None);
    c.dry();
    // the cape: strokes fanning out from the neck, a bell to the knee
    let p = body(cape);
    let mut cb = h.take(Tool::round_sable, 0.07, p, 1.0);
    for (i, k) in [-3.0f32, 3.0, -2.0, 2.0, -1.0, 1.0, 0.0].iter().enumerate() {
        if i % 2 == 0 {
            cb.reload(p, 1.0);
        }
        let (u0, u1) = (k * 0.018, k * 0.045 + h.rng.normal() * 0.006);
        h.mark(c, &mut cb, Mark { pts: &[(u0, 0.83), ((u0 + u1) * 0.5, 0.6), (u1, 0.36)], pressure: (0.6, 1.0), ramps: (0.05, 0.1) }, None);
    }
    cb.reload(p, 1.0);
    h.line(c, &mut cb, &[(-0.105, 0.77), (-0.05, 0.835), (0.05, 0.835), (0.105, 0.77)], 0.75, 0.75);
    h.line(c, &mut cb, &[(-0.15, 0.37), (0.0, 0.355), (0.15, 0.37)], 0.7, 0.7);
    c.dry();
    // the hand on the stick
    let mut hb = h.take(Tool::round_sable, 0.035, thin(dark), 0.8 * 0.45);
    h.dab(c, &mut hb, 0.15, 0.5, 0.03, FRAC_PI_2, 0.9);
    // head, then the beret: a wide flat dab resting on it, tipped a little
    let mut hd = h.take(Tool::round_sable, 0.06, thin(hair), 1.0 * 0.45);
    h.dab(c, &mut hd, 0.0, 0.88, 0.05, FRAC_PI_2, 1.0);
    let mut be = h.take(Tool::round_sable, 0.04, thin(dark), 1.0 * 0.45);
    h.mark(c, &mut be, Mark { pts: &[(-0.068, 0.905), (0.0, 0.922), (0.064, 0.915)], pressure: (0.85, 0.9), ramps: (0.05, 0.2) }, None);
    if let Some(l) = rim {
        c.dry();
        let mut lb = h.take(Tool::round_sable, 0.014, lean(paint::color::mix(dark, l, 0.5, paint::Mix::Pigment)), 0.35 * 0.4);
        h.mark(c, &mut lb, Mark { pts: &[(-0.1, 0.785), (-0.05, 0.842), (0.03, 0.845)], pressure: (0.4, 0.25), ramps: (0.2, 0.5) }, None);
    }
    h.p(-0.08, 0.8)
}

/// The slimmer young man in a frock coat, white collar and student cap, his
/// right hand resting on `hand_on` (canvas units) if given.
#[allow(clippy::too_many_arguments)]
pub fn youth_in_frock(c: &mut Canvas, at: (f32, f32), size: f32, coat: Rgb, dark: Rgb, hair: Rgb, collar: Rgb, hand_on: Option<(f32, f32)>, rim: Option<Rgb>, seed: u64) {
    let mut h = Hand::new(at, size, seed);
    legs(c, &mut h, paint::color::mix(dark, coat, 0.3, paint::Mix::Pigment), dark, 0.025, 0.04);
    // frock coat: narrow torso to the waist, then tails flaring to the knee
    let p = body(coat);
    let mut cb = h.take(Tool::round_sable, 0.055, p, 1.0);
    for (i, u) in [-0.04f32, 0.04, 0.0].iter().enumerate() {
        if i % 2 == 0 {
            cb.reload(p, 1.0);
        }
        h.mark(c, &mut cb, Mark { pts: &[(*u, 0.82), (u * 0.85, 0.68), (u * 0.8, 0.56)], pressure: (0.8, 0.75), ramps: (0.05, 0.1) }, None);
    }
    cb.reload(p, 1.0);
    for u in [-0.035f32, 0.035, 0.0] {
        h.mark(c, &mut cb, Mark { pts: &[(u * 0.9, 0.58), (u * 1.2, 0.45), (u * 1.6, 0.33)], pressure: (0.7, 0.9), ramps: (0.05, 0.15) }, None);
    }
    h.line(c, &mut cb, &[(-0.085, 0.765), (-0.04, 0.825), (0.04, 0.825), (0.085, 0.765)], 0.7, 0.7);
    // left arm hangs at his side
    h.line(c, &mut cb, &[(-0.07, 0.78), (-0.085, 0.64), (-0.08, 0.5)], 0.6, 0.5);
    // right arm to the companion's shoulder
    if let Some(t) = hand_on {
        let tu = (t.0 - at.0) / size;
        let tv = (at.1 - t.1) / size;
        let e = (0.5 * (0.07 + tu) + 0.02, 0.5 * (0.78 + tv) - 0.06);
        h.mark(c, &mut cb, Mark { pts: &[(0.065, 0.78), e, (tu, tv)], pressure: (0.65, 0.5), ramps: (0.05, 0.2) }, None);
    } else {
        h.line(c, &mut cb, &[(0.07, 0.78), (0.085, 0.64), (0.08, 0.5)], 0.6, 0.5);
    }
    c.dry();
    // white collar standing up at the neck
    let mut wc = h.take(Tool::round_sable, 0.022, thin(collar), 0.8 * 0.45);
    h.mark(c, &mut wc, Mark { pts: &[(-0.03, 0.832), (0.0, 0.842), (0.03, 0.832)], pressure: (0.7, 0.7), ramps: (0.1, 0.3) }, None);
    // head, then the cap: a small flat dab resting on it
    let mut hd = h.take(Tool::round_sable, 0.055, thin(hair), 1.0 * 0.45);
    h.dab(c, &mut hd, 0.0, 0.882, 0.045, FRAC_PI_2, 1.0);
    let mut cp = h.take(Tool::round_sable, 0.036, thin(dark), 1.0 * 0.45);
    h.mark(c, &mut cp, Mark { pts: &[(-0.042, 0.905), (0.0, 0.918), (0.045, 0.91)], pressure: (0.85, 0.85), ramps: (0.05, 0.2) }, None);
    if let Some(l) = rim {
        c.dry();
        let mut lb = h.take(Tool::round_sable, 0.012, lean(paint::color::mix(dark, l, 0.5, paint::Mix::Pigment)), 0.35 * 0.4);
        h.mark(c, &mut lb, Mark { pts: &[(-0.08, 0.775), (-0.04, 0.832)], pressure: (0.4, 0.25), ramps: (0.2, 0.5) }, None);
    }
}
