//! Running a painting from the command line: options, stage timing, stopping
//! early to look at a stage, and the finishing recipe (varnish, cracks,
//! raking light) paintings share.
//!
//!   cargo paint <name>                       1000px preview → out/<name>.png
//!   cargo paint <name> -- --full             3200px         → out/<name>_full.png
//!   cargo paint <name> -- --width 1600 --seed 7 --out path.png
//!   cargo paint <name> -- --stop sky         save right after the "sky" stage
//!   cargo paint <name> -- --no-cracks        skip craquelure in the finish

use paint::{Canvas, Fbm, Pigment, Rgb, hex};
use std::path::PathBuf;
use std::time::Instant;

pub struct Run {
    pub width: usize,
    pub seed: u64,
    pub out: PathBuf,
    stop: Option<String>,
    no_cracks: bool,
    t0: Instant,
}

impl Run {
    pub fn new(name: &str) -> Self {
        let args: Vec<String> = std::env::args().collect();
        let get = |flag: &str| args.iter().position(|a| a == flag).and_then(|i| args.get(i + 1));
        let has = |flag: &str| args.iter().any(|a| a == flag);
        let full = has("--full");
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../out");
        let out = match get("--out") {
            Some(p) => p.into(),
            None if full => root.join(format!("{name}_full.png")),
            None => root.join(format!("{name}.png")),
        };
        Run {
            width: get("--width").and_then(|s| s.parse().ok()).unwrap_or(if full { 3200 } else { 1000 }),
            seed: get("--seed").and_then(|s| s.parse().ok()).unwrap_or(1),
            out,
            stop: get("--stop").cloned(),
            no_cracks: has("--no-cracks"),
            t0: Instant::now(),
        }
    }

    /// A stage of the painting is done: report the time, and if the run was
    /// asked to stop here, save the canvas and return true (the caller then
    /// returns). Saving dries the wet paint, so a run only saves at its end.
    #[must_use]
    pub fn stage(&self, c: &mut Canvas, name: &str) -> bool {
        eprintln!("  {name:<10} {:>6.2}s", self.t0.elapsed().as_secs_f32());
        if self.stop.as_deref() == Some(name) {
            self.save(c);
            return true;
        }
        false
    }

    /// Finish the painting (see `Finish`) and save it.
    pub fn finish(&self, c: &mut Canvas, f: &Finish) {
        c.dry();
        let var = Fbm::new(self.seed as u32 + 98, 3, 400.0);
        let (base, vary) = (f.varnish_coats, f.varnish_vary);
        c.glaze(&Pigment::varnish(f.varnish), None, |x, y| base + vary * var.get(x, y));
        if let (Some((cell, strength)), false) = (f.cracks, self.no_cracks) {
            c.craquelure(cell, strength, self.seed);
        }
        c.relief(f.relief.0, f.relief.1);
        if !self.stage(c, "finish") {
            self.save(c);
        }
    }

    pub fn save(&self, c: &mut Canvas) {
        c.save(&self.out).unwrap();
        let p = self.out.canonicalize().unwrap_or(self.out.clone());
        eprintln!("wrote {} ({}px) in {:.1}s", p.display(), self.width, self.t0.elapsed().as_secs_f32());
    }
}

/// How a painting is finished: aged varnish (a clear, yellowing film,
/// uneven), craquelure, then the surface lit by raking light.
pub struct Finish {
    pub varnish: Rgb,
    /// Varnish thickness in coats, and how much it varies across the canvas.
    pub varnish_coats: f32,
    pub varnish_vary: f32,
    /// Crack cell size (units) and darkening, if the surface has cracked.
    pub cracks: Option<(f32, f32)>,
    /// Relief lighting strength and gloss.
    pub relief: (f32, f32),
}

impl Finish {
    /// An old varnished painting.
    pub fn aged(relief: (f32, f32)) -> Self {
        Finish { varnish: hex("#e6d3a4"), varnish_coats: 0.4, varnish_vary: 0.12, cracks: Some((12.0, 0.12)), relief }
    }
}
//! Evergreens written as brush gestures: the spruce as Friedrich places it,
//! a dark spire of drooping tiers (the evergreen against the dead oak).

use paint::{Canvas, Hand, Mark, Paint, Rgb, Tool};

/// A spruce: a trunk line, then tiers of drooping branch strokes from the top
/// down, each tier a little longer, the tip a single flick. `base` is where
/// the trunk meets the ground; `height` in canvas units.
pub fn spruce(c: &mut Canvas, base: (f32, f32), height: f32, color: Rgb, seed: u64) {
    let mut h = Hand::new(base, height, seed);
    h.tremor = 0.002;
    let p = Paint { color, hiding: 0.92, stiff: 0.6 };
    let mut t = h.take(Tool::round_sable, 0.014, p, 0.6);
    h.mark(c, &mut t, Mark { pts: &[(0.0, 0.0), (0.002, 0.5), (0.0, 1.0)], pressure: (0.9, 0.3), ramps: (0.0, 0.3) }, None);
    let mut b = h.take(Tool::round_sable, 0.028, p, 0.6);
    let tiers = 22 + (height / 12.0).min(16.0) as usize;
    let slim = h.rng.range(0.17, 0.24);
    for i in 0..tiers {
        let v = 0.96 - (i as f32 + h.rng.range(0.0, 0.6)) / tiers as f32 * 0.9;
        let reach = (0.015 + slim * (1.0 - v)) * h.rng.range(0.75, 1.1);
        if i % 3 == 0 {
            b.reload(p, 0.6);
        }
        for s in [-1.0f32, 1.0] {
            // out and down from the trunk, the tip turning a little up
            let droop = reach * h.rng.range(0.25, 0.45);
            let pts = [(s * 0.004, v), (s * reach * 0.55, v - droop), (s * reach, v - droop * 0.8)];
            h.mark(c, &mut b, Mark { pts: &pts, pressure: (0.9, 0.35), ramps: (0.0, 0.5) }, None);
        }
    }
    // the leader at the top
    h.mark(c, &mut t, Mark { pts: &[(0.0, 0.92), (0.001, 1.02)], pressure: (0.7, 0.2), ramps: (0.0, 0.5) }, None);
}
//! Brush physics study sheet: each row tests one behavior.

use paint::{Gesture, Held, Orient, Paint, Tool, hex};

fn main() {
    let o = paintings::run::Run::new("study_brushes");
    // lead-white priming on linen
    let mut c = paint::Canvas::new(o.width, 1.5, hex("#ece6d8")).with_linen(paint::Linen::fine(3));

    let ultramarine = hex("#1f2a78");
    let sienna = hex("#8a3b12");
    let sap = hex("#4f6b1c");
    let ivory_black = hex("#1a1816");
    let cad_yellow = hex("#f2c200");
    let cobalt = hex("#1c4fa0");
    let crimson = hex("#9a1030");
    let white = hex("#f4f1e8");
    let ochre = hex("#c08a2a");

    let wave = |x0: f32, y: f32, len: f32, amp: f32| -> Vec<(f32, f32)> {
        (0..6).map(|i| {
            let t = i as f32 / 5.0;
            (x0 + t * len, y + (t * std::f32::consts::TAU).sin() * amp)
        }).collect()
    };

    // ---- row 1: each tool, fully loaded, one S-stroke
    let tools = [
        (Tool::round_sable(8.0), ultramarine),
        (Tool::hog_flat(20.0), sienna),
        (Tool::filbert(16.0), sap),
        (Tool::fan(26.0), ivory_black),
        (Tool::rigger(1.6), ivory_black),
    ];
    for (i, (t, col)) in tools.iter().enumerate() {
        let mut b = Held::new(t.clone(), 10 + i as u64);
        b.load(Paint::body(*col), 1.0);
        let x = 30.0 + i as f32 * 190.0;
        c.drag(&mut b, &Gesture::new(wave(x, 60.0, 160.0, 14.0)), None);
    }

    // ---- row 2: pressure falls off → dry brush over the weave
    let mut b = Held::new(Tool::hog_flat(22.0), 20);
    b.load(Paint::body(sienna), 0.8);
    c.drag(&mut b, &Gesture::line((30.0, 150.0), (470.0, 150.0)).pressure(1.0, 0.12).ramps(0.03, 0.02), None);
    let mut b = Held::new(Tool::round_sable(10.0), 21);
    b.load(Paint::body(ultramarine), 0.5);
    c.drag(&mut b, &Gesture::new(wave(520.0, 150.0, 450.0, 8.0)).pressure(0.9, 0.3), None);

    // ---- row 3: wet into wet — yellow dragged through wet blue picks it up
    let mut b = Held::new(Tool::hog_flat(24.0), 30);
    for k in 0..4 {
        b.reload(Paint::body(cobalt), 1.0);
        let y = 215.0 + k as f32 * 16.0;
        c.drag(&mut b, &Gesture::line((30.0, y), (330.0, y)).pressure(0.9, 0.8), None);
    }
    let mut b = Held::new(Tool::filbert(14.0), 31);
    for k in 0..5 {
        b.reload(Paint::body(cad_yellow), 1.0);
        let x = 60.0 + k as f32 * 55.0;
        c.drag(&mut b, &Gesture::line((x, 200.0), (x + 20.0, 290.0)).pressure(0.95, 0.9), None);
    }
    // white into wet dark
    let mut b = Held::new(Tool::hog_flat(24.0), 32);
    for k in 0..4 {
        b.reload(Paint::body(ivory_black), 1.0);
        let y = 215.0 + k as f32 * 16.0;
        c.drag(&mut b, &Gesture::line((370.0, y), (620.0, y)), None);
    }
    let mut b = Held::new(Tool::round_sable(9.0), 33);
    b.load(Paint::body(white), 1.0);
    c.drag(&mut b, &Gesture::new(vec![(390.0, 280.0), (450.0, 215.0), (520.0, 280.0), (600.0, 210.0)]).pressure(0.9, 0.7), None);

    // blender: two wet colors side by side, badger zigzag across the join
    let mut b = Held::new(Tool::hog_flat(24.0), 34);
    for k in 0..5 {
        b.reload(Paint::body(ochre), 1.0);
        let y = 205.0 + k as f32 * 16.0;
        c.drag(&mut b, &Gesture::line((660.0, y), (810.0, y)), None);
        b.reload(Paint::body(crimson), 1.0);
        c.drag(&mut b, &Gesture::line((810.0, y), (970.0, y)), None);
    }
    let mut bl = Held::new(Tool::badger(34.0), 35);
    let zig: Vec<(f32, f32)> = (0..10).map(|i| (790.0 + if i % 2 == 0 { -18.0 } else { 18.0 }, 200.0 + i as f32 * 10.0)).collect();
    c.drag(&mut bl, &Gesture::new(zig).pressure(0.5, 0.5), None);
    let zig2: Vec<(f32, f32)> = (0..10).map(|i| (840.0 + if i % 2 == 0 { -14.0 } else { 14.0 }, 200.0 + i as f32 * 10.0)).collect();
    c.drag(&mut bl, &Gesture::new(zig2).pressure(0.35, 0.35), None);

    // ---- row 4: let it dry, then glaze crimson over part of rows 3
    c.dry();
    let mut g = Held::new(Tool::filbert(30.0), 40);
    for k in 0..3 {
        g.reload(Paint::glaze(crimson), 1.0 * 0.3);
        let y = 215.0 + k as f32 * 22.0;
        c.drag(&mut g, &Gesture::line((180.0, y), (520.0, y)).pressure(0.6, 0.6), None);
    }

    // ---- row 5: Cézanne-style hatching with a flat at a fixed angle, and fan dabs
    let mut b = Held::new(Tool::hog_flat(12.0), 50);
    let greens = [hex("#5a7a3a"), hex("#7d9a4a"), hex("#3f5f3a"), hex("#9aa860"), hex("#6f8fa0")];
    let mut r = paint::Rng::new(5);
    for k in 0..60 {
        b.reload(Paint::body(greens[k % greens.len()]), 0.7);
        let x = 40.0 + r.range(0.0, 380.0);
        let y = 340.0 + r.range(0.0, 90.0);
        let a = -0.9f32;
        c.drag(&mut b, &Gesture::line((x, y), (x + a.cos() * 18.0, y + a.sin() * 18.0)).orient(Orient::Fixed(a + std::f32::consts::FRAC_PI_2)).pressure(0.85, 0.7), None);
    }
    let mut fan = Held::new(Tool::fan(30.0), 51);
    for k in 0..14 {
        fan.reload(Paint::scumble(if k % 2 == 0 { hex("#3d5a2a") } else { hex("#8aa050") }), 0.5 * 0.6);
        let x = 480.0 + k as f32 * 34.0;
        let y = 400.0 + r.range(-20.0, 20.0);
        c.drag(&mut fan, &Gesture::line((x, y + 10.0), (x + 6.0, y - 30.0)).orient(Orient::Across).pressure(0.6, 0.3), None);
    }

    // ---- row 6: one dirty brush dragged across wet colors without cleaning
    let bands = [cobalt, cad_yellow, crimson, white, sap];
    let mut b = Held::new(Tool::hog_flat(26.0), 60);
    for (k, col) in bands.iter().enumerate() {
        b.reload(Paint::body(*col), 1.0);
        let x = 40.0 + k as f32 * 70.0;
        c.drag(&mut b, &Gesture::line((x, 480.0), (x, 610.0)).orient(Orient::Across), None);
    }
    let mut b = Held::new(Tool::filbert(18.0), 61);
    b.load(Paint::body(white), 0.6);
    for k in 0..3 {
        let y = 505.0 + k as f32 * 40.0;
        c.drag(&mut b, &Gesture::line((25.0, y), (400.0, y + 8.0)).pressure(0.9, 0.9), None);
    }
    // rigger twigs
    let mut rg = Held::new(Tool::rigger(1.4), 62);
    for k in 0..8 {
        rg.reload(Paint::body(ivory_black), 1.0);
        let x = 500.0 + k as f32 * 55.0;
        let pts: Vec<(f32, f32)> = (0..6).map(|i| (x + (i as f32 * 1.7).sin() * 8.0 + i as f32 * 6.0, 620.0 - i as f32 * 22.0)).collect();
        c.drag(&mut rg, &Gesture::new(pts).pressure(0.9, 0.2).ramps(0.02, 0.6), None);
    }

    c.relief(0.7, 0.04);
    o.save(&mut c);
}
//! Calibration sheet for the physical surface: a Friedrich canvas as bought
//! (linen + ground), then thin fluid paint (should pool in the ground's
//! hollows), a lean sky scumble and stiff body paint (should keep its marks).
//! Top band: bare ground. Then thin smalt-blue paint, a stiff white stroke
//! band, and a dark glaze.

use paint::{Gesture, Held, Mask, Orient, Paint, Pigment, Style, Tool, hex};

fn main() {
    let o = paintings::run::Run::new("study_ground");
    let st = Style::friedrich();
    let mut c = st.prepare(o.width, 2.0, o.seed);
    if o.stage(&mut c, "ground") {
        return;
    }
    let h = c.height();
    // band 2: thin fluid blue, laid with a soft filbert in long strokes
    let fr = c.frame();
    let band = |a: f32, b: f32| Mask::from_fn(fr, move |_, y| if y >= a * h && y < b * h { 1.0 } else { 0.0 });
    let b2 = band(0.25, 0.5);
    let mut fil = Held::new(Tool::filbert(30.0), 3);
    for i in 0..12 {
        fil.reload(Paint { color: hex("#5d6f94"), hiding: 0.35, stiff: 0.15 }, 0.8 * 0.15);
        let y = h * 0.26 + i as f32 * h * 0.02;
        c.drag(&mut fil, &Gesture::new(vec![(0.0, y), (1000.0, y)]).pressure(0.8, 0.8).orient(Orient::Across), Some(&b2));
    }
    c.dry();
    // band 3: stiff lead white, hog brush, keeps its marks
    let b3 = band(0.5, 0.75);
    let mut hog = Held::new(Tool::hog_flat(24.0), 4);
    for i in 0..10 {
        hog.reload(Paint { color: hex("#e6e1d3"), hiding: 0.9, stiff: 1.0 }, 1.0 * 1.0);
        let y = h * 0.51 + i as f32 * h * 0.024;
        c.drag(&mut hog, &Gesture::new(vec![(0.0, y), (500.0, y + 2.0), (1000.0, y)]).pressure(0.85, 0.85).orient(Orient::Across), Some(&b3));
    }
    c.dry();
    // band 4: a dark umber glaze
    let b4 = band(0.75, 1.0);
    c.glaze(&Pigment::transparent(hex("#3b2a1c")), Some(&b4), |_, _| 2.0);
    c.relief(0.35, 0.02);
    o.save(&mut c);
}
//! Study sheet for the oak and Rückenfigur generators.

use paint::{Oak, Style, hex};
use paintings::figures;

fn main() {
    let o = paintings::run::Run::new("study_motifs");
    let mut c = Style::friedrich().prepare(o.width, 1.6, 1);
    let h = c.height();

    // top row: oaks with different settings
    let ground = h * 0.5;
    for (i, (gnarl, broken, lean, depth)) in
        [(0.5, 0.08, 0.0, 5), (0.7, 0.18, 0.08, 5), (0.9, 0.35, -0.15, 4), (0.7, 0.12, 0.0, 5), (1.0, 0.3, 0.2, 4), (0.6, 0.05, -0.05, 5)]
            .iter()
            .enumerate()
    {
        let x = 90.0 + i as f32 * 165.0;
        let mut oak = Oak::new((x, ground), 250.0, 11 + i as u64 * 7);
        oak.gnarl = *gnarl;
        oak.broken = *broken;
        oak.lean = *lean;
        oak.depth = *depth;
        oak.roots = if i == 4 { 4 } else { 2 };
        oak.paint(&mut c, hex("#2a2420"), Some(hex("#8a7f6a")), 100 + i as u64);
    }

    // bottom row: figures, each written as brush gestures
    let gy = h * 0.96;
    let fh = 190.0;
    let (robe, pale, rim) = (hex("#14120f"), hex("#a8986f"), hex("#8f8a78"));
    figures::monk(&mut c, (140.0, gy), fh, robe, pale, None, 1);
    // the two men: the youth, a little higher, leans on the older man
    let sh = figures::man_in_cape(&mut c, (520.0, gy), fh, hex("#3a3f33"), hex("#15130f"), hex("#2a2119"), Some(rim), 2);
    figures::youth_in_frock(&mut c, (455.0, gy - 8.0), fh * 0.99, hex("#394034"), hex("#15130f"), hex("#33281c"), hex("#d6cfbd"), Some(sh), Some(rim), 3);
    // the monk again, small, as he is in the painting (44 units)
    figures::monk(&mut c, (800.0, gy), 44.0, robe, pale, None, 4);

    c.relief(0.5, 0.0);
    o.save(&mut c);
}

//! Simulated bristle brushes working in wet paint.
//!
//! A `Tool` is a physical brush (round sable, hog flat, filbert, fan, rigger,
//! badger blender). `Held` is that brush in the hand: every bristle has its
//! own little reservoir of paint (volume + Mixbox pigment mix + hiding).
//!
//! As the handle moves along a `Gesture`:
//! - bristles splay with pressure and their tips trail behind the motion,
//!   lagging on turns (a first-order bend model, after the verlet bristles in
//!   dli/paint: https://github.com/dli/paint);
//! - a bristle touches the canvas only where its reach clears the canvas tooth
//!   and the paint relief, so light pressure catches only the weave's peaks
//!   (dry-brush);
//! - each bristle swept capsule exchanges paint with the wet layer: it
//!   deposits a share of its load and picks up wet paint, so brushes get dirty,
//!   colors smear and mix on the canvas, and a clean brush blends;
//! - moving bristles plough wet paint aside and ahead, so ridges and ends of
//!   strokes build up by themselves.

use crate::path::densify;
use crate::canvas::Canvas;
use crate::mask::Mask;
use crate::rng::Rng;
use crate::smoothstep;
use crate::wet::{LAT, Latent, Paint, Prop, mix_into};

/// Relief (µm) that spans a bristle's contact range: a bristle pressed
/// lightly touches only peaks this much above their surroundings.
const TOOTH_UM: f32 = 60.0;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Kind {
    Round,
    Flat,
    Filbert,
    Fan,
    Rigger,
    Blender,
}

#[derive(Clone, Debug)]
pub struct Tool {
    pub kind: Kind,
    /// Footprint width at full pressure (units).
    pub width: f32,
    pub bristles: usize,
    /// How far tips trail behind the contact at full pressure (units).
    pub length: f32,
    /// 0 = soft hair (sable, badger) .. 1 = stiff hog bristle.
    pub stiffness: f32,
    /// Bristle thickness multiplier (overlap between bristles).
    pub hair: f32,
    /// Stroke length (units) over which a load runs down (e-folding).
    pub run: f32,
    /// Paint thickness laid at the start of a fully loaded stroke.
    pub lay: f32,
    /// Fraction of wet paint a bristle takes up per pass.
    pub pickup: f32,
    /// Fraction of wet paint a moving bristle ploughs aside per pass.
    pub push: f32,
    /// Footprint growth under pressure.
    pub splay: f32,
    /// Unevenness of bristle lengths (ragged edges, broken marks).
    pub ragged: f32,
}

impl Tool {
    fn base(kind: Kind, width: f32) -> Self {
        Tool {
            kind,
            width,
            bristles: 80,
            length: width * 0.7,
            stiffness: 0.4,
            hair: 1.3,
            run: 40.0 + 6.0 * width,
            lay: 1.0,
            pickup: 0.12,
            push: 0.1,
            splay: 0.3,
            ragged: 0.25,
        }
    }

    /// Soft pointed round: smooth, precise, little ploughing. Friedrich's detail brush.
    pub fn round_sable(width: f32) -> Self {
        Tool { stiffness: 0.2, pickup: 0.1, push: 0.05, splay: 0.45, ragged: 0.15, ..Self::base(Kind::Round, width) }
    }

    /// Stiff hog-bristle flat: square marks, strong ridges, broken edges.
    pub fn hog_flat(width: f32) -> Self {
        Tool {
            bristles: 140,
            length: width * 0.5,
            stiffness: 0.85,
            hair: 1.1,
            run: 25.0 + 4.0 * width,
            lay: 1.4,
            pickup: 0.2,
            push: 0.3,
            splay: 0.12,
            ragged: 0.45,
            ..Self::base(Kind::Flat, width)
        }
    }

    /// Filbert: oval hog/synthetic, soft-ended marks, good for blending forms.
    pub fn filbert(width: f32) -> Self {
        Tool { bristles: 120, stiffness: 0.6, lay: 1.2, pickup: 0.18, push: 0.18, ragged: 0.3, ..Self::base(Kind::Filbert, width) }
    }

    /// Fan: sparse spread bristles, for foliage, grasses and feathering.
    pub fn fan(width: f32) -> Self {
        Tool { bristles: 36, hair: 0.6, stiffness: 0.5, lay: 0.7, pickup: 0.1, push: 0.08, splay: 0.2, ragged: 0.5, ..Self::base(Kind::Fan, width) }
    }

    /// Rigger / liner: a few very long soft hairs. Twigs, rigging, fine lines.
    pub fn rigger(width: f32) -> Self {
        Tool {
            bristles: 14,
            length: width * 5.0,
            stiffness: 0.08,
            hair: 1.4,
            run: 250.0,
            lay: 1.0,
            pickup: 0.04,
            push: 0.02,
            splay: 0.6,
            ragged: 0.1,
            ..Self::base(Kind::Rigger, width)
        }
    }

    /// Badger blender: big, soft, used clean to fuse wet paint.
    pub fn badger(width: f32) -> Self {
        Tool {
            bristles: 160,
            length: width * 0.6,
            stiffness: 0.15,
            lay: 0.0,
            run: 30.0,
            pickup: 0.3,
            push: 0.04,
            splay: 0.5,
            ragged: 0.2,
            ..Self::base(Kind::Blender, width)
        }
    }

    /// Bristle radius in units.
    pub(crate) fn hair_radius(&self) -> f32 {
        let across = match self.kind {
            Kind::Flat => 0.36,
            Kind::Filbert => 0.6,
            Kind::Fan => 0.12,
            _ => 1.0,
        };
        // area the bristles share, divided among them
        let area = self.width * 0.5 * self.width * 0.5 * across * std::f32::consts::PI;
        (area / (self.bristles as f32 * std::f32::consts::PI)).sqrt() * self.hair
    }
}

#[derive(Clone, Debug)]
pub(crate) struct Bristle {
    /// Root offset in the brush frame (x along the wide axis), roughly −1..1.
    rx: f32,
    ry: f32,
    len: f32,
    /// Pressure needed before this bristle touches.
    thresh: f32,
    bend: (f32, f32),
    seed: u64,
    prev: [Option<(f32, f32)>; 2],
    pub(crate) vol: f32,
    lat: Latent,
    hide: Prop,
}

/// A brush in the hand, with paint in its bristles.
pub struct Held {
    pub tool: Tool,
    pub(crate) bristles: Vec<Bristle>,
}

impl Held {
    pub fn new(tool: Tool, seed: u64) -> Self {
        let mut rng = Rng::new(seed);
        let n = tool.bristles.max(1);
        let golden = std::f32::consts::PI * (3.0 - 5f32.sqrt());
        let bristles = (0..n)
            .map(|i| {
                let t = (i as f32 + 0.5) / n as f32;
                let (rx, ry) = match tool.kind {
                    Kind::Round | Kind::Rigger | Kind::Blender => {
                        let r = t.sqrt();
                        let a = i as f32 * golden;
                        (r * a.cos(), r * a.sin())
                    }
                    Kind::Filbert => {
                        let r = t.sqrt();
                        let a = i as f32 * golden;
                        (r * a.cos(), r * a.sin() * 0.3)
                    }
                    Kind::Flat => (rng.range(-1.0, 1.0), rng.range(-0.18, 0.18)),
                    Kind::Fan => {
                        let a = rng.range(-0.95, 0.95);
                        (a.sin(), (a.cos() - 1.0) * 0.35 + rng.range(-0.04, 0.04))
                    }
                };
                // jitter roots a little so bristles don't sit on a perfect lattice
                let (rx, ry) = ((rx + rng.normal() * 0.02).clamp(-ROOT_MAX, ROOT_MAX), (ry + rng.normal() * 0.02).clamp(-ROOT_MAX, ROOT_MAX));
                Bristle {
                    rx,
                    ry,
                    len: (1.0 + rng.normal() * 0.15 * tool.ragged).clamp(0.4, LEN_MAX),
                    // a round brush is shaped to a point: the outer hairs are
                    // shorter and touch only under pressure, so a light touch
                    // or a lift-off gives just the tip
                    thresh: tool.ragged * rng.f().powf(1.5) * 0.55
                        + match tool.kind {
                            Kind::Round | Kind::Rigger => 0.6 * (rx * rx + ry * ry),
                            Kind::Filbert => 0.3 * (rx * rx + ry * ry / 0.09),
                            _ => 0.0,
                        },
                    bend: (0.0, 0.0),
                    seed: i as u64 * 7919 + seed,
                    prev: [None, None],
                    vol: 0.0,
                    lat: [0.0; LAT],
                    hide: [0.5, 0.5],
                }
            })
            .collect();
        Held { tool, bristles }
    }

    /// A full load's volume for one bristle.
    pub(crate) fn full(&self) -> f32 {
        // neighbouring bristles overlap by ~hair², so each lays lay / hair²
        let track = 2.0 * self.tool.hair_radius();
        self.tool.lay.max(0.3) * track * self.tool.run / (self.tool.hair * self.tool.hair)
    }

    /// Dip the brush: mix `amount` (0..1 of a full load) of `paint` into
    /// every bristle's reservoir. Bristles hold a little more or less.
    pub fn load(&mut self, paint: Paint, amount: f32) {
        let lat = paint.latent();
        let full = self.full();
        for (i, b) in self.bristles.iter_mut().enumerate() {
            let k = 0.75 + 0.5 * crate::rng::hash2(i as i64, 17, 3);
            mix_into(&mut b.vol, &mut b.lat, &mut b.hide, amount * full * k, &lat, [paint.hiding, paint.stiff]);
        }
    }

    /// Wipe the brush on a rag: remove `frac` of the paint in it.
    pub fn wipe(&mut self, frac: f32) {
        for b in &mut self.bristles {
            b.vol *= 1.0 - frac.clamp(0.0, 1.0);
        }
    }

    /// Wipe thoroughly and load fresh paint.
    pub fn reload(&mut self, paint: Paint, amount: f32) {
        self.wipe(0.85);
        self.load(paint, amount);
    }

    /// Paint left in the brush, relative to a full load.
    pub fn fullness(&self) -> f32 {
        let f = self.full();
        self.bristles.iter().map(|b| b.vol).sum::<f32>() / (f * self.bristles.len() as f32)
    }
}

/// How the brush's wide axis is held.
#[derive(Clone, Copy, Debug)]
pub enum Orient {
    /// Wide axis across the direction of travel (full-width marks).
    Across,
    /// Wide axis along the travel (thin edge marks).
    Along,
    /// Fixed angle in radians, regardless of travel (e.g. Cézanne hatching).
    Fixed(f32),
}

/// One movement of the hand.
#[derive(Clone, Debug)]
pub struct Gesture {
    pub pts: Vec<(f32, f32)>,
    /// Pressure at the start and end (0..1).
    pub pressure: (f32, f32),
    pub orient: Orient,
    /// Fraction of the stroke spent pressing down / lifting off.
    pub attack: f32,
    pub release: f32,
    /// Hand unsteadiness: 1 = a normal hand, 0 = mechanically exact.
    pub shake: f32,
}

impl Gesture {
    pub fn new(pts: Vec<(f32, f32)>) -> Self {
        Gesture { pts, pressure: (0.8, 0.8), orient: Orient::Across, attack: 0.08, release: 0.15, shake: 1.0 }
    }
    pub fn line(a: (f32, f32), b: (f32, f32)) -> Self {
        Self::new(vec![a, b])
    }
    /// Scale hand unsteadiness (0 = exact, 1 = normal).
    pub fn shake(mut self, k: f32) -> Self {
        self.shake = k;
        self
    }
    pub fn pressure(mut self, a: f32, b: f32) -> Self {
        self.pressure = (a, b);
        self
    }
    pub fn orient(mut self, o: Orient) -> Self {
        self.orient = o;
        self
    }
    pub fn ramps(mut self, attack: f32, release: f32) -> Self {
        self.attack = attack;
        self.release = release;
        self
    }
    fn pressure_at(&self, u: f32) -> f32 {
        let base = self.pressure.0 + (self.pressure.1 - self.pressure.0) * u;
        let a = if self.attack > 0.0 { 0.08 + 0.92 * smoothstep(0.0, self.attack, u) } else { 1.0 };
        let r = if self.release > 0.0 { 0.05 + 0.95 * smoothstep(0.0, self.release, 1.0 - u) } else { 1.0 };
        base * a * r
    }
}

/// Raw view of the wet layer and surface, so brushes working disjoint parts
/// of the canvas can run in parallel (see `Canvas::work`).
#[derive(Clone, Copy)]
pub(crate) struct Surf {
    w: usize,
    h: usize,
    scale: f32,
    vol: *mut f32,
    lat: *mut Latent,
    hide: *mut Prop,
    stroke: *mut u32,
    touched: *mut u32,
    floor: *mut f32,
    base: *const f32,
}
// SAFETY: callers only run brushes concurrently on pixel sets that cannot
// overlap (tiles separated by more than the largest stroke extent).
unsafe impl Send for Surf {}
unsafe impl Sync for Surf {}

/// Dirty pixel bounds collected by a drag.
pub(crate) type Bounds = Option<(usize, usize, usize, usize)>;

fn grow(b: &mut Bounds, x0: usize, y0: usize, x1: usize, y1: usize) {
    *b = Some(match *b {
        None => (x0, y0, x1, y1),
        Some((a, c, d, e)) => (a.min(x0), c.min(y0), d.max(x1), e.max(y1)),
    });
}

impl Surf {
    #[inline]
    unsafe fn add(&self, i: usize, v: f32, lat: &Latent, hide: Prop) {
        unsafe {
            if v <= 0.0 {
                return;
            }
            let vol = &mut *self.vol.add(i);
            let l = &mut *self.lat.add(i);
            let hd = &mut *self.hide.add(i);
            let t = *vol + v;
            let a = v / t;
            for k in 0..LAT {
                l[k] += (lat[k] - l[k]) * a;
            }
            hd[0] += (hide[0] - hd[0]) * a;
            hd[1] += (hide[1] - hd[1]) * a;
            *vol = t;
        }
    }
}

impl Canvas {
    pub(crate) fn surf(&mut self) -> Surf {
        // the raw views below index 0..w*h: every buffer must be that long
        let n = self.f.w * self.f.h;
        let wt = &self.wet;
        assert!(
            [self.height.len(), self.px.len(), self.film.len(), wt.vol.len(), wt.lat.len(), wt.hide.len(), wt.stroke.len(), wt.touched.len(), wt.floor.len()].iter().all(|&l| l == n),
            "canvas buffers out of sync with frame"
        );
        if self.base.as_ref().map(|b| b.0) != Some(self.surf_gen) {
            let mut base = self.base.take().map(|b| b.1).unwrap_or_default();
            base.resize(self.height.len(), 0.0);
            use rayon::prelude::*;
            // a brush rests on local peaks: only relief relative to the
            // surroundings (within ~1.5 mm) matters. ±TOOTH_UM of relief spans
            // the whole contact range.
            let r = ((1.5 / self.px_mm()).round() as usize).max(1);
            let (w, h) = (self.f.w, self.f.h);
            let low = crate::surface::box_blur(&crate::surface::box_blur(&self.height, w, h, r), w, h, r);
            base.par_iter_mut().zip(self.height.par_iter().zip(low.par_iter())).for_each(|(b, (&hgt, &lo))| {
                *b = (0.5 + (hgt - lo) / (2.0 * TOOTH_UM)).clamp(-0.2, 1.3);
            });
            self.base = Some((self.surf_gen, base));
        }
        Surf {
            w: self.f.w,
            h: self.f.h,
            scale: self.f.scale,
            vol: self.wet.vol.as_mut_ptr(),
            lat: self.wet.lat.as_mut_ptr(),
            hide: self.wet.hide.as_mut_ptr(),
            stroke: self.wet.stroke.as_mut_ptr(),
            touched: self.wet.touched.as_mut_ptr(),
            floor: self.wet.floor.as_mut_ptr(),
            base: self.base.as_ref().unwrap().1.as_ptr(),
        }
    }

    pub(crate) fn next_stroke_ids(&mut self, n: u32) -> u32 {
        let first = self.wet.current.wrapping_add(1).max(1);
        self.wet.current = first.wrapping_add(n);
        first
    }

    /// Drag a held brush through a gesture, working the wet paint.
    pub fn drag(&mut self, held: &mut Held, g: &Gesture, clip: Option<&Mask>) {
        if let Some(m) = clip {
            self.check_mask(m);
        }
        let id = self.next_stroke_ids(1);
        let surf = self.surf();
        let mut scratch = Vec::new();
        // SAFETY: exclusive &mut self, single brush.
        let b = unsafe { drag_on(surf, held, g, clip, id, &mut scratch) };
        if let Some((x0, y0, x1, y1)) = b {
            self.wet.touch(x0, y0, x1, y1);
        }
    }
}

/// Bristle roots never sit farther than this (in half-widths) from the axis.
const ROOT_MAX: f32 = 1.2;
/// Longest bristle relative to the tool's length.
const LEN_MAX: f32 = 1.6;

/// A pixel rectangle (x0, y0, x1, y1), end-exclusive.
pub(crate) type Rect = (usize, usize, usize, usize);

/// Every pixel `drag_on` may read or write for a gesture with these points
/// (units), as a conservative end-exclusive rectangle clamped to the canvas.
/// Mirrors the geometry in `drag_on`/`exchange`: the resampled path (a spline
/// can overshoot its control points), hand shake, root offsets with wander
/// and splay, bristle bend (it relaxes from zero toward targets bounded by
/// the trail and spread), the capsule radius, and the plough destination.
pub(crate) fn footprint(tool: &Tool, pts: &[(f32, f32)], shake: f32, scale: f32, w: usize, h: usize) -> Option<Rect> {
    if pts.is_empty() {
        return None;
    }
    let s = scale;
    let px: Vec<(f32, f32)> = pts.iter().map(|&(x, y)| (x * s, y * s)).collect();
    let path = if px.len() >= 2 { densify(&px) } else { px };
    let (mut x0, mut y0, mut x1, mut y1) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
    for &(x, y) in &path {
        x0 = x0.min(x);
        y0 = y0.min(y);
        x1 = x1.max(x);
        y1 = y1.max(y);
    }
    let shake_px = shake.abs() * (0.05 * tool.width + 0.12) * s * 1.5;
    let half = tool.width * 0.5 * s * (1.0 + tool.splay.abs() * 0.5);
    let root = (ROOT_MAX + 0.12 * tool.ragged.abs()) * std::f32::consts::SQRT_2 * half;
    let bend = tool.length * s * LEN_MAX + root * tool.splay.abs() * 0.3;
    let rb = (tool.hair_radius() * s).max(0.55);
    // exchange rect: capsule ± (rb + 1); plough target ≤ off from a pixel in
    // it, off = rb + 1; bounds padding off + 2; plus rounding
    let pad = shake_px + root + bend * 0.6 + (rb + 1.0) + 2.0 * (rb + 1.0) + 4.0;
    if !pad.is_finite() || !x0.is_finite() || !x1.is_finite() || !y0.is_finite() || !y1.is_finite() {
        panic!("non-finite brush footprint (gesture or tool parameters)");
    }
    let c = |v: f32, n: usize| (v.max(0.0) as usize).min(n);
    let r = (c((x0 - pad).floor(), w), c((y0 - pad).floor(), h), c((x1 + pad).ceil() + 1.0, w), c((y1 + pad).ceil() + 1.0, h));
    if r.2 <= r.0 || r.3 <= r.1 { None } else { Some(r) }
}

/// SAFETY: no other thread may touch pixels in `footprint(..)` of `g`.
pub(crate) unsafe fn drag_on(
    sf: Surf,
    held: &mut Held,
    g: &Gesture,
    clip: Option<&Mask>,
    id: u32,
    scratch: &mut Vec<f32>,
) -> Bounds {
    let mut bounds: Bounds = None;
    if g.pts.is_empty() {
        return bounds;
    }
    let s = sf.scale;
    let pts: Vec<(f32, f32)> = g.pts.iter().map(|&(x, y)| (x * s, y * s)).collect();
    let path = if pts.len() >= 2 { densify(&pts) } else { vec![pts[0], pts[0]] };
    let mut arc = vec![0.0f32; path.len()];
    for i in 1..path.len() {
        let (dx, dy) = (path[i].0 - path[i - 1].0, path[i].1 - path[i - 1].1);
        arc[i] = arc[i - 1] + (dx * dx + dy * dy).sqrt();
    }
    let total = arc[arc.len() - 1];
    let tool = held.tool.clone();
    let rb = (tool.hair_radius() * s).max(0.55);
    let full = held.full();
    let step = rb.max(1.25);
    let nsteps = ((total / step).ceil() as usize).max(1);
    let bend_len = tool.length * (0.25 + 0.75 * (1.0 - tool.stiffness));

    for b in &mut held.bristles {
        b.prev = [None, None];
        b.bend = (0.0, 0.0);
    }
    let mut seg = 0usize;
    let mut last_dir = (1.0f32, 0.0f32);
    for k in 0..=nsteps {
        let d = (k as f32 * step).min(total);
        while seg + 1 < path.len() - 1 && arc[seg + 1] < d {
            seg += 1;
        }
        let seg_len = (arc[seg + 1] - arc[seg]).max(1e-6);
        let f = ((d - arc[seg]) / seg_len).clamp(0.0, 1.0);
        let (ax, ay) = path[seg];
        let (bx, by) = path[seg + 1];
        let hx = ax + (bx - ax) * f;
        let hy = ay + (by - ay) * f;
        let dir = if seg_len > 1e-3 { ((bx - ax) / seg_len, (by - ay) / seg_len) } else { last_dir };
        last_dir = dir;
        // the hand is never exact: the path drifts sideways a little and the
        // pressure breathes, both slowly along the stroke
        let lw = (tool.width * 2.5 + 6.0) * s;
        let hs = id as u64 * 7919;
        let off = g.shake * (0.05 * tool.width + 0.12) * s * (wander(d / lw, hs + 1) + 0.5 * wander(d / (lw * 0.37), hs + 2));
        let (hx, hy) = (hx - dir.1 * off, hy + dir.0 * off);
        let u = if total > 0.0 { d / total } else { 0.5 };
        let p = (g.pressure_at(u) * (1.0 + g.shake * 0.14 * wander(d / (lw * 0.8), hs + 3))).clamp(0.0, 1.0);
        let theta = match g.orient {
            Orient::Across => dir.1.atan2(dir.0) + std::f32::consts::FRAC_PI_2,
            Orient::Along => dir.1.atan2(dir.0),
            Orient::Fixed(a) => a,
        };
        let (st, ct) = theta.sin_cos();
        let half = tool.width * 0.5 * s * (0.45 + 0.55 * p) * (1.0 + tool.splay * (p - 0.5));
        let rate = 1.0 - (-(step / s) / (bend_len + 1e-3)).exp();

        for b in held.bristles.iter_mut() {
            let reach = (p - b.thresh) / (1.0 - b.thresh).max(1e-3);
            if reach <= 0.0 {
                b.prev = [None, None];
                continue;
            }
            // bristles wander a little across the stroke
            let wv = wander(d / s / tool.width.max(2.0) * 1.3, b.seed) * tool.ragged;
            let (ox, oy) = ((b.rx + wv * 0.12) * half, (b.ry + wv * 0.05) * half);
            let root = (hx + ox * ct - oy * st, hy + ox * st + oy * ct);
            // tips trail behind the motion and splay outward under pressure
            let trail = tool.length * s * b.len * p;
            let spread = tool.splay * p * 0.3;
            let target = (-dir.0 * trail + (ox * ct - oy * st) * spread, -dir.1 * trail + (ox * st + oy * ct) * spread);
            b.bend.0 += (target.0 - b.bend.0) * rate;
            b.bend.1 += (target.1 - b.bend.1) * rate;
            // one contact point: the belly-to-tip region of the bent bristle
            let cur = (root.0 + b.bend.0 * 0.6, root.1 + b.bend.1 * 0.6);
            let prev = b.prev[0].unwrap_or(cur);
            unsafe { exchange(sf, b, &tool, prev, cur, rb, reach, full, clip, id, scratch, &mut bounds) };
            b.prev[0] = Some(cur);
        }
    }
    bounds
}

/// Smooth 1-D value noise, −1..1.
fn wander(t: f32, seed: u64) -> f32 {
    let i = t.floor();
    let f = t - i;
    let f = f * f * (3.0 - 2.0 * f);
    let a = crate::rng::hash2(i as i64, 0, seed);
    let b = crate::rng::hash2(i as i64 + 1, 0, seed);
    (a + (b - a) * f) * 2.0 - 1.0
}

/// Paint exchange between one bristle and the canvas along the capsule
/// swept from `a` to `b` (pixels).
#[allow(clippy::too_many_arguments)]
unsafe fn exchange(
    sf: Surf,
    br: &mut Bristle,
    tool: &Tool,
    a: (f32, f32),
    b: (f32, f32),
    rb: f32,
    reach: f32,
    full: f32,
    clip: Option<&Mask>,
    id: u32,
    wts: &mut Vec<f32>,
    bounds: &mut Bounds,
) {
    unsafe {
        let (w, h) = (sf.w, sf.h);
        let s = sf.scale;
        let px_area = 1.0 / (s * s);
        let x0 = ((a.0.min(b.0) - rb - 1.0).floor().max(0.0)) as usize;
        let y0 = ((a.1.min(b.1) - rb - 1.0).floor().max(0.0)) as usize;
        let x1 = ((a.0.max(b.0) + rb + 1.0).ceil().max(0.0) as usize).min(w);
        let y1 = ((a.1.max(b.1) + rb + 1.0).ceil().max(0.0) as usize).min(h);
        if x1 <= x0 || y1 <= y0 {
            return;
        }
        let (dx, dy) = (b.0 - a.0, b.1 - a.1);
        let seg2 = dx * dx + dy * dy;
        let seg = seg2.sqrt();
        let (mx, my) = if seg > 1e-4 { (dx / seg, dy / seg) } else { (0.0, 0.0) };
        let (nx, ny) = (-my, mx);
        // lowest surface height this bristle reaches down to
        let th = 1.0 - reach * 1.6;

        // pass 1: contact weights
        let bw = x1 - x0;
        wts.clear();
        wts.resize(bw * (y1 - y0), 0.0);
        let mut sum_w = 0.0f32;
        let mut sum_cov = 0.0f32;
        for y in y0..y1 {
            for x in x0..x1 {
                let (px, py) = (x as f32 + 0.5, y as f32 + 0.5);
                let t = if seg2 > 1e-8 { (((px - a.0) * dx + (py - a.1) * dy) / seg2).clamp(0.0, 1.0) } else { 0.0 };
                let (qx, qy) = (a.0 + dx * t - px, a.1 + dy * t - py);
                let dist = (qx * qx + qy * qy).sqrt();
                if dist > rb + 0.5 {
                    continue;
                }
                let cov = 1.0 - smoothstep(rb * 0.5, rb + 0.5, dist);
                sum_cov += cov;
                let i = y * w + x;
                let surf = (*sf.base.add(i) + 0.35 * *sf.vol.add(i)).min(1.5);
                // soft hair bends down into the valleys of the weave; stiff hog
                // bristles ride on the peaks
                let give = 0.15 + 0.45 * (1.0 - tool.stiffness).clamp(0.0, 1.0);
                let contact = smoothstep(th - give, th + 0.2, surf);
                let mut wt = cov * contact;
                if let Some(m) = clip {
                    wt *= m.data[i];
                }
                wts[(y - y0) * bw + (x - x0)] = wt;
                sum_w += wt;
            }
        }
        if sum_w <= 1e-6 {
            return;
        }

        // deposit: a share of the load, proportional to distance traveled
        let travel = (seg / s).max(rb / s * 0.5);
        // only the part of the footprint actually in contact takes paint: a
        // bristle skimming the weave peaks keeps most of its load
        let touch = (sum_w / sum_cov.max(1e-6)).min(1.0);
        let dep_total = br.vol * (1.0 - (-travel / tool.run).exp()) * touch;
        let dep_per_w = dep_total / sum_w / px_area;
        // film splitting: a bristle in wet paint always lifts some of it, even
        // when loaded; a spent bristle drinks more
        let hunger = 0.35 + 0.65 * (1.0 - br.vol / full).clamp(0.0, 1.0).powf(1.5);
        let push_k = tool.push * (seg / (2.0 * rb)).clamp(0.0, 1.0);
        let off = rb + 1.0;

        let mut got_v = 0.0f32;
        let mut got_l = [0.0f32; LAT];
        let mut got_h: Prop = [0.0, 0.0];
        let (blat, bhide) = (br.lat, br.hide);
        for y in y0..y1 {
            for x in x0..x1 {
                let wt = wts[(y - y0) * bw + (x - x0)];
                if wt <= 0.0 {
                    continue;
                }
                let i = y * w + x;
                let vol = &mut *sf.vol.add(i);
                // one stroke lifts only part of the film
                if *sf.touched.add(i) != id {
                    *sf.touched.add(i) = id;
                    *sf.floor.add(i) = *vol * (1.0 - tool.pickup);
                }
                let v = *vol;
                if v > 1e-6 {
                    let own = if *sf.stroke.add(i) == id { 0.15 } else { 1.0 };
                    let take = (v * tool.pickup * wt * hunger * own).min((v - *sf.floor.add(i)).max(0.0));
                    if take > 0.0 {
                        *vol -= take;
                        let tv = take * px_area;
                        got_v += tv;
                        let l = &*sf.lat.add(i);
                        for k in 0..LAT {
                            got_l[k] += l[k] * tv;
                        }
                        let hp = *sf.hide.add(i);
                        got_h[0] += hp[0] * tv;
                        got_h[1] += hp[1] * tv;
                    }
                }
                if dep_per_w > 0.0 {
                    sf.add(i, dep_per_w * wt, &blat, bhide);
                    *sf.stroke.add(i) = id;
                }
                // plough: move paint outward from the bristle's path, and ahead
                if push_k > 0.0 {
                    let v = *sf.vol.add(i);
                    let m = v * push_k * wt;
                    if m > 1e-6 {
                        let (px, py) = (x as f32 + 0.5, y as f32 + 0.5);
                        let side = if (px - a.0) * nx + (py - a.1) * ny >= 0.0 { 1.0 } else { -1.0 };
                        let tx = px + (nx * side * 0.75 + mx * 0.45) * off;
                        let ty = py + (ny * side * 0.75 + my * 0.45) * off;
                        if tx >= 0.0 && ty >= 0.0 && (tx as usize) < w && (ty as usize) < h {
                            let j = ty as usize * w + tx as usize;
                            // a clipped stroke can't push paint past its mask:
                            // only the accepted share moves, the rest stays
                            let m = m * clip.map_or(1.0, |c| c.data[j]);
                            if j != i && m > 0.0 {
                                let l = *sf.lat.add(i);
                                let hd = *sf.hide.add(i);
                                *sf.vol.add(i) -= m;
                                sf.add(j, m, &l, hd);
                            }
                        }
                    }
                }
            }
        }
        br.vol = (br.vol - dep_total).max(0.0);
        if got_v > 0.0 {
            for k in 0..LAT {
                got_l[k] /= got_v;
            }
            got_h[0] /= got_v;
            got_h[1] /= got_v;
            mix_into(&mut br.vol, &mut br.lat, &mut br.hide, got_v, &got_l, got_h);
        }
        let pad = (off + 2.0) as usize;
        grow(bounds, x0.saturating_sub(pad), y0.saturating_sub(pad), (x1 + pad).min(w), (y1 + pad).min(h));
    }
}

//! Gnarled oaks in the manner of Friedrich (e.g. "Oak Tree in the Snow",
//! "The Abbey in the Oakwood"): a tall leader that keeps going up, crooked
//! side limbs made of straight lengths joined by sharp elbows, broken stubs,
//! an open crown, and short claw-like twigs all along the outer limbs.
//! Grown recursively, then painted with simulated brushes: each limb is one
//! drag of a round sable sized to it, twigs with a rigger, light with a
//! dry-brush pass on the lit side.

use crate::bristle::{Gesture, Held, Orient, Tool};
use crate::canvas::Canvas;
use crate::color::Rgb;
use crate::mask::Mask;
use crate::rng::Rng;
use crate::shape::Shape;
use crate::wet::Paint;
use std::f32::consts::{FRAC_PI_2, PI};

#[derive(Clone, Debug)]
pub struct Limb {
    pub pts: Vec<(f32, f32)>,
    /// Full width at each point (units).
    pub w: Vec<f32>,
    pub depth: u32,
}

#[derive(Clone, Debug)]
pub struct Oak {
    /// Base of the trunk (units).
    pub base: (f32, f32),
    /// Rough overall height (units).
    pub height: f32,
    /// Trunk width at the base (units).
    pub trunk: f32,
    /// Lean of the trunk in radians (+ = right).
    pub lean: f32,
    /// 0 = straight, 1 = very gnarled.
    pub gnarl: f32,
    /// Branching depth (4–6).
    pub depth: u32,
    /// Probability a limb is broken off (dead oak ≈ 0.3).
    pub broken: f32,
    /// Twig clusters per unit of outer limb length.
    pub twigs: f32,
    /// Exposed roots at the base.
    pub roots: u32,
    pub seed: u64,
}

impl Oak {
    pub fn new(base: (f32, f32), height: f32, seed: u64) -> Self {
        Oak { base, height, trunk: height * 0.06, lean: 0.0, gnarl: 0.7, depth: 5, broken: 0.18, twigs: 0.14, roots: 2, seed }
    }

    pub fn grow(&self) -> Vec<Limb> {
        let mut rng = Rng::new(self.seed);
        let mut out = Vec::new();
        self.leader(&mut out, &mut rng);
        for i in 0..self.roots {
            let side = if i % 2 == 0 { 1.0 } else { -1.0 };
            let a = FRAC_PI_2 - side * rng.range(1.1, 1.45); // out and a little down
            let start = (self.base.0 + side * self.trunk * 0.25, self.base.1 - self.trunk * 0.15);
            let rl = self.height * rng.range(0.05, 0.1);
            let w = self.trunk * 0.55;
            self.limb(&mut out, &mut rng, start, a, rl, w, self.depth, 0.0, false);
        }
        out
    }

    /// The trunk continues upward as a leader, thinning, throwing side limbs.
    fn leader(&self, out: &mut Vec<Limb>, rng: &mut Rng) {
        // the trunk runs up to where it splits into two or three main limbs
        let total = self.height * rng.range(0.38, 0.55);
        let nseg = 5;
        let seg = total / nseg as f32;
        let (mut x, mut y) = self.base;
        let mut a = -FRAC_PI_2 + self.lean;
        let mut pts = vec![(x, y)];
        let mut ws = vec![self.trunk * 1.25]; // flare at the foot
        let mut kids = Vec::new();
        let mut side = if rng.chance(0.5) { 1.0 } else { -1.0 };
        for i in 1..=nseg {
            let t = i as f32 / nseg as f32;
            if i > 1 && rng.chance(0.35 * self.gnarl) {
                a += rng.range(0.15, 0.4) * if rng.chance(0.5) { 1.0 } else { -1.0 };
            }
            a += angle_diff(-FRAC_PI_2 + self.lean, a) * 0.35;
            x += a.cos() * seg;
            y += a.sin() * seg;
            let w = self.trunk * (1.0 - 0.3 * t);
            pts.push((x, y));
            ws.push(w);
            // limbs start a third of the way up, alternating sides
            if t > 0.45 && t < 0.95 && rng.chance(0.6) {
                let n = 1;
                for _ in 0..n {
                    side = -side;
                    let a2 = -FRAC_PI_2 + side * rng.range(0.7, 1.45);
                    let len = self.height * rng.range(0.22, 0.42) * (1.1 - 0.5 * t);
                    kids.push(((x, y), a2, len, w * rng.range(0.5, 0.8), side));
                }
            }
            // stubs of lost limbs
            if rng.chance(0.3 * self.broken / 0.18) {
                let s = if rng.chance(0.5) { 1.0 } else { -1.0 };
                let a2 = -FRAC_PI_2 + s * rng.range(0.9, 1.6);
                let l = w * rng.range(0.8, 2.2);
                out.push(Limb { pts: vec![(x, y), (x + a2.cos() * l, y + a2.sin() * l)], w: vec![w * 0.45, w * 0.4], depth: 1 });
            }
        }
        // the split: main limbs going up and out
        let n = if rng.chance(0.4) { 3 } else { 2 };
        let w_top = *ws.last().unwrap();
        for k in 0..n {
            let u = if n == 1 { 0.0 } else { k as f32 / (n - 1) as f32 * 2.0 - 1.0 };
            let a2 = a + u * rng.range(0.35, 0.7) + rng.normal() * 0.1;
            let s = if u == 0.0 { side_of(a2 + 0.001) } else { u.signum() };
            let len = self.height * rng.range(0.3, 0.45);
            kids.push(((x, y), a2, len, w_top * rng.range(0.6, 0.8), s));
        }
        out.push(Limb { pts, w: ws, depth: 0 });
        for (p, a2, l2, w2, s) in kids {
            self.limb(out, rng, p, a2, l2, w2, 1, s, true);
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn limb(
        &self,
        out: &mut Vec<Limb>,
        rng: &mut Rng,
        start: (f32, f32),
        angle: f32,
        len: f32,
        width: f32,
        depth: u32,
        side: f32,
        can_break: bool,
    ) {
        if depth > self.depth + 1 || width < 0.1 || len < 0.8 {
            return;
        }
        let broken = can_break && depth <= 3 && rng.chance(self.broken);
        let len = if broken { len * rng.range(0.2, 0.45) } else { len };
        // a few straight lengths joined by elbows
        let nseg = (2.0 + len / 18.0).clamp(2.0, 5.0) as usize;
        let mut pts = vec![start];
        let mut ws = vec![width];
        let mut a = angle;
        let (mut x, mut y) = start;
        // outer limbs turn back upward at elbows; some droop and recover
        let up = -FRAC_PI_2 + side * rng.range(0.35, 0.8);
        let mut kids = Vec::new();
        for i in 1..=nseg {
            let t = i as f32 / nseg as f32;
            let seg = len / nseg as f32 * rng.range(0.7, 1.3);
            x += a.cos() * seg;
            y += a.sin() * seg;
            let w = width * (1.0 - 0.55 * t);
            pts.push((x, y));
            ws.push(w);
            // elbow: a sharp turn, mostly back toward "up", sometimes away
            let elbow = rng.range(0.3, 0.95) * self.gnarl;
            let toward = angle_diff(up, a).signum();
            a += if rng.chance(0.72) { toward * elbow } else { -toward * elbow * 0.8 };
            if i < nseg && !broken && rng.chance(0.55) {
                let s = if rng.chance(0.5) { 1.0 } else { -1.0 };
                let a2 = a + s * rng.range(0.6, 1.3);
                kids.push(((x, y), a2, len * rng.range(0.45, 0.7), w * rng.range(0.45, 0.7), side_of(a2)));
            }
        }
        let tip = (x, y);
        let tip_w = *ws.last().unwrap();
        out.push(Limb { pts: pts.clone(), w: ws.clone(), depth });
        if broken {
            return;
        }
        for (p, a2, l2, w2, s) in kids {
            self.limb(out, rng, p, a2, l2, w2, depth + 1, s, true);
        }
        if depth < self.depth {
            let l2 = len * rng.range(0.55, 0.8);
            let a2 = a + rng.normal() * 0.25;
            self.limb(out, rng, tip, a2, l2, tip_w * 0.8, depth + 1, side, true);
        }
        // claw-like twig clusters along the outer limbs
        if depth + 2 >= self.depth {
            let total: f32 = pts.windows(2).map(|p| dist(p[0], p[1])).sum();
            let n = (total * self.twigs * rng.range(0.6, 1.4)).round() as usize;
            for _ in 0..n {
                let (bi, t) = pick_along(&pts, rng.f());
                let p0 = lerp(pts[bi], pts[bi + 1], t);
                let w0 = (ws[bi] * 0.4).clamp(0.1, 0.28);
                let mut a2 = -FRAC_PI_2 + rng.normal() * 0.9;
                let mut p = p0;
                let mut tp = vec![p];
                let mut tw = vec![w0];
                let l = self.height * rng.range(0.015, 0.045);
                for k in 0..3 {
                    p = (p.0 + a2.cos() * l / 3.0, p.1 + a2.sin() * l / 3.0);
                    tp.push(p);
                    tw.push(w0 * (0.7 - 0.2 * k as f32).max(0.2));
                    a2 += rng.range(0.3, 0.9) * if rng.chance(0.5) { 1.0 } else { -1.0 };
                }
                out.push(Limb { pts: tp, w: tw, depth: depth + 2 });
            }
        }
    }

    /// Silhouette mask of the limbs (for glazing, mist, clipping).
    pub fn mask(&self, c: &Canvas, limbs: &[Limb]) -> Mask {
        let mut shape = Shape::new();
        for l in limbs {
            shape = shape.ribbon(&l.pts, &l.w);
        }
        Mask::from_shape(c.f, shape)
    }

    /// Paint the tree with simulated brushes: every limb a single drag of a
    /// round sable as wide as the limb (the bristles give bark streaks), twigs
    /// with a rigger, then a light dry-brush pass along the lit edge.
    pub fn paint(&self, c: &mut Canvas, dark: Rgb, light: Option<Rgb>, seed: u64) -> Mask {
        let limbs = self.grow();
        let mut rng = Rng::new(seed);
        // thick to thin, like a painter blocking the tree in
        let mut order: Vec<&Limb> = limbs.iter().collect();
        order.sort_by(|a, b| b.w[0].partial_cmp(&a.w[0]).unwrap());
        let paint = Paint { color: dark, hiding: 0.95, stiff: 0.9 };
        for l in &order {
            let w0 = l.w[0];
            let w1 = *l.w.last().unwrap();
            let tool = if w0 < 0.9 {
                Tool { width: w0 * 1.6, length: w0 * 3.0, splay: 0.15, stiffness: 0.3, ragged: 0.05, ..Tool::rigger(w0) }
            } else {
                Tool { width: w0, length: w0 * 0.5, ragged: 0.35, ..Tool::round_sable(w0) }
            };
            let mut held = Held::new(tool, rng.next_u64());
            held.load(paint, 0.9);
            // pressure sets the width: full at the base, lighter to the tip
            let p1 = (w1 / w0).clamp(0.15, 1.0);
            let g = Gesture::new(l.pts.clone()).pressure(1.0, p1).ramps(0.0, if l.depth > 2 { 0.4 } else { 0.1 }).orient(Orient::Across);
            c.drag(&mut held, &g, None);
            // a stub from a broken limb ends blunt: dab the end
        }
        if let Some(lc) = light {
            // let the dark dry, then drag a lean light scumble along the lit
            // edge with hardly any pressure: it catches only the ridges of the
            // bark strokes and the canvas tooth, broken like real dry-brush
            c.dry();
            let mask = self.mask(c, &limbs);
            // model each big limb as a lit cylinder: a few thin lean streaks
            // laid along the limb on the side facing the light (upper left),
            // stepping from half-tone near the axis to the lightest near the
            // edge; low pressure so the canvas tooth and the bark ridges break
            // them up, and each covers a random stretch of the limb
            let light_dir = (-0.75f32, -0.66f32);
            for l in limbs.iter().filter(|l| l.w[0] > 2.0) {
                let n = l.pts.len();
                let normals: Vec<(f32, f32)> = (0..n)
                    .map(|i| {
                        let a = l.pts[i.saturating_sub(1)];
                        let b = l.pts[(i + 1).min(n - 1)];
                        let (dx, dy) = (b.0 - a.0, b.1 - a.1);
                        let d = (dx * dx + dy * dy).sqrt().max(1e-4);
                        let nn = (-dy / d, dx / d);
                        if nn.0 * light_dir.0 + nn.1 * light_dir.1 >= 0.0 { nn } else { (-nn.0, -nn.1) }
                    })
                    .collect();
                // how squarely the limb faces the light: vertical limbs get a
                // clear lit side, limbs pointing at the light hardly any
                let facing = normals.iter().map(|nn| (nn.0 * light_dir.0 + nn.1 * light_dir.1).max(0.0)).sum::<f32>() / n as f32;
                let streaks = 2 + (l.w[0] / 3.0).min(3.0) as usize;
                for k in 0..streaks {
                    let u = 0.12 + 0.3 * (k as f32 + rng.range(0.0, 0.8)) / streaks as f32;
                    let tone = (0.25 + 0.75 * (k + 1) as f32 / streaks as f32) * (0.4 + 0.6 * facing);
                    let pts: Vec<(f32, f32)> = (0..n)
                        .map(|i| {
                            let w = l.w[i];
                            (l.pts[i].0 + normals[i].0 * w * u, l.pts[i].1 + normals[i].1 * w * u)
                        })
                        .collect();
                    // a random stretch of the limb
                    let a = rng.range(0.0, 0.4);
                    let b = (a + rng.range(0.35, 0.9)).min(1.0);
                    let sub = sub_path(&pts, a, b);
                    let col = crate::color::mix(dark, lc, tone, crate::color::Mix::Pigment);
                    let tool = Tool { ragged: 0.6, ..Tool::round_sable(l.w[0] * rng.range(0.1, 0.18)) };
                    let mut held = Held::new(tool, rng.next_u64());
                    held.load(Paint { color: col, hiding: 0.6, stiff: 0.4 }, rng.range(0.4, 0.8) * 0.4);
                    let g = Gesture::new(sub).pressure(rng.range(0.3, 0.5), rng.range(0.15, 0.3)).ramps(0.2, 0.4).orient(Orient::Across);
                    c.drag(&mut held, &g, Some(&mask));
                }
            }
            return mask;
        }
        self.mask(c, &limbs)
    }
}

fn dist(a: (f32, f32), b: (f32, f32)) -> f32 {
    ((a.0 - b.0).powi(2) + (a.1 - b.1).powi(2)).sqrt()
}

fn lerp(a: (f32, f32), b: (f32, f32), t: f32) -> (f32, f32) {
    (a.0 + (b.0 - a.0) * t, a.1 + (b.1 - a.1) * t)
}

/// Segment index and fraction at arc-length fraction `u` along a polyline.
fn pick_along(pts: &[(f32, f32)], u: f32) -> (usize, f32) {
    let total: f32 = pts.windows(2).map(|p| dist(p[0], p[1])).sum();
    let mut target = u * total;
    for i in 0..pts.len() - 1 {
        let d = dist(pts[i], pts[i + 1]);
        if target <= d || i == pts.len() - 2 {
            return (i, (target / d.max(1e-6)).clamp(0.0, 1.0));
        }
        target -= d;
    }
    (0, 0.0)
}

fn angle_diff(target: f32, a: f32) -> f32 {
    let mut d = target - a;
    while d > PI {
        d -= 2.0 * PI;
    }
    while d < -PI {
        d += 2.0 * PI;
    }
    d
}

fn side_of(a: f32) -> f32 {
    if a.cos() >= 0.0 { 1.0 } else { -1.0 }
}

/// The part of a polyline between arc-length fractions `a` and `b`.
fn sub_path(pts: &[(f32, f32)], a: f32, b: f32) -> Vec<(f32, f32)> {
    let (i0, t0) = pick_along(pts, a);
    let (i1, t1) = pick_along(pts, b);
    let mut out = vec![lerp(pts[i0], pts[i0 + 1], t0)];
    for p in &pts[i0 + 1..=i1] {
        out.push(*p);
    }
    out.push(lerp(pts[i1], pts[i1 + 1], t1));
    out
}
