//! Wet paint sitting on top of the dry picture.
//!
//! Every pixel holds a volume of wet paint (thickness, in "layer units": 1.0
//! is one normal coat), its pigment mixture as a Mixbox latent vector (mixing
//! is linear in latent space, weighted by volume) and its hiding power
//! (0 = pure glaze, 1 = fully opaque body color). Brushes exchange paint with
//! this layer. `Canvas::dry` bakes it into the dry picture with Kubelka–Munk.

use crate::canvas::Canvas;
use crate::color::Rgb;
use crate::pigment::Pigment;
use crate::surface::COAT_UM;
use rayon::prelude::*;

pub const LAT: usize = mixbox::LATENT_SIZE;
pub type Latent = [f32; LAT];
/// Paint properties mixed by volume alongside the pigment: [hiding, stiffness].
/// Stiffness 0 = fluid, medium-rich glaze; 1 = stiff tube paint.
pub type Prop = [f32; 2];

#[inline]
fn lerp_prop(p: &mut Prop, q: Prop, a: f32) {
    p[0] += (q[0] - p[0]) * a;
    p[1] += (q[1] - p[1]) * a;
}

/// A paint as squeezed from the tube and thinned with medium.
#[derive(Clone, Copy, Debug)]
pub struct Paint {
    pub color: Rgb,
    /// Hiding power at unit thickness: 0.05 = glaze, 0.5 = scumble, 0.92 = body.
    pub hiding: f32,
    /// Stiffness: 0 = fluid, rich in medium (a glaze), 1 = stiff tube paint.
    /// Sets how the paint levels as it dries (see `surface::settle`). How
    /// much paint goes on the brush is the separate `amount` of `Held::load`.
    pub stiff: f32,
}

impl Paint {
    pub fn new(color: Rgb, hiding: f32, stiff: f32) -> Self {
        Paint { color, hiding, stiff }
    }
    pub fn body(color: Rgb) -> Self {
        Paint { color, hiding: 0.92, stiff: 1.0 }
    }
    pub fn scumble(color: Rgb) -> Self {
        Paint { color, hiding: 0.5, stiff: 0.6 }
    }
    pub fn glaze(color: Rgb) -> Self {
        Paint { color, hiding: 0.07, stiff: 0.3 }
    }
    pub fn latent(&self) -> Latent {
        mixbox::linear_float_rgb_to_latent(&self.color)
    }
}

pub(crate) struct Wet {
    pub(crate) vol: Vec<f32>,
    pub(crate) lat: Vec<Latent>,
    /// [hiding, stiffness] of the wet paint.
    pub(crate) hide: Vec<Prop>,
    /// Which stroke last laid paint here (a stroke barely re-picks its own paint).
    pub(crate) stroke: Vec<u32>,
    /// Stroke that last touched a pixel, and the film floor that stroke may
    /// not lift below (one pass lifts only part of the film).
    pub(crate) touched: Vec<u32>,
    pub(crate) floor: Vec<f32>,
    /// Id of the stroke being painted.
    pub(crate) current: u32,
    /// Dirty bounding box in pixels (x0, y0, x1, y1), if any paint is wet.
    pub(crate) dirty: Option<(usize, usize, usize, usize)>,
}

impl Wet {
    pub fn new(n: usize) -> Self {
        Wet { vol: vec![0.0; n], lat: vec![[0.0; LAT]; n], hide: vec![[0.0, 0.5]; n], stroke: vec![0; n], touched: vec![0; n], floor: vec![0.0; n], current: 0, dirty: None }
    }

    pub fn touch(&mut self, x0: usize, y0: usize, x1: usize, y1: usize) {
        self.dirty = Some(match self.dirty {
            None => (x0, y0, x1, y1),
            Some((a, b, c, d)) => (a.min(x0), b.min(y0), c.max(x1), d.max(y1)),
        });
    }

}

/// Mix `v` of (`lat`, `hide`) into a reservoir (`rv`, `rl`, `rh`).
#[inline]
pub fn mix_into(rv: &mut f32, rl: &mut Latent, rh: &mut Prop, v: f32, lat: &Latent, hide: Prop) {
    if v <= 0.0 {
        return;
    }
    let t = *rv + v;
    let a = v / t;
    for k in 0..LAT {
        rl[k] += (lat[k] - rl[k]) * a;
    }
    lerp_prop(rh, hide, a);
    *rv = t;
}


impl Canvas {
    /// Let the wet paint dry: the film levels over the surface (thin fluid
    /// paint pools in the hollows, stiff paint keeps its marks), then it is
    /// composited over the dry picture with Kubelka–Munk using the settled
    /// thickness, and the wet layer is cleared.
    pub fn dry(&mut self) {
        let Some((x0, y0, x1, y1)) = self.wet.dirty.take() else { return };
        let (w, h) = (self.f.w, self.f.h);
        let (x1, y1) = (x1.min(w), y1.min(h));
        let pad = ((2.0 / self.px_mm()).ceil() as usize).max(2);
        let ex = (x0.saturating_sub(pad), y0.saturating_sub(pad), (x1 + pad).min(w), (y1 + pad).min(h));
        let (ew, eh) = (ex.2 - ex.0, ex.3 - ex.1);
        let mut add = vec![0.0f32; ew * eh];
        let mut stiff = vec![0.5f32; ew * eh];
        for y in 0..eh {
            for x in 0..ew {
                let i = (ex.1 + y) * w + ex.0 + x;
                let v = self.wet.vol[i];
                if v >= 1e-5 {
                    add[y * ew + x] = v * COAT_UM;
                    stiff[y * ew + x] = self.wet.hide[i][1];
                }
            }
        }
        let t = self.settle(ex, &add, &stiff);
        let wet = &mut self.wet;
        let (lat, hide) = (&wet.lat, &wet.hide);
        self.px[ex.1 * w..ex.3 * w]
            .par_chunks_mut(w)
            .zip(wet.vol[ex.1 * w..ex.3 * w].par_chunks_mut(w))
            .zip(self.film[ex.1 * w..ex.3 * w].par_chunks_mut(w))
            .enumerate()
            .for_each(|(j, ((px, vv), ff))| {
                let y = ex.1 + j;
                for x in ex.0..ex.2 {
                    if vv[x] < 1e-5 {
                        vv[x] = 0.0;
                        continue;
                    }
                    let ti = t[j * ew + x - ex.0] / COAT_UM;
                    let i = y * w + x;
                    let c = mixbox::latent_to_linear_float_rgb(&lat[i]);
                    let pig = Pigment::with_hiding(c, hide[i][0].clamp(0.01, 0.99));
                    px[x] = pig.over(px[x], ti);
                    ff[x] += ti;
                    vv[x] = 0.0;
                }
            });
    }

    /// Total wet paint on the canvas (for tests / debugging).
    pub fn wet_total(&self) -> f64 {
        self.wet.vol.iter().map(|&v| v as f64).sum::<f64>() / (self.f.scale as f64 * self.f.scale as f64)
    }
}
//! Kubelka–Munk pigments, following Curtis et al. 1997, "Computer-Generated
//! Watercolor", section 5.1:
//! https://grail.cs.washington.edu/wp-content/uploads/2015/08/curtis-1997-cgw.pdf
//!
//! A pigment is specified by how a unit-thickness layer looks over white and
//! over black. From that we derive absorption K and scattering S per channel,
//! then composite layers of any thickness over whatever is already painted.

use crate::color::Rgb;

#[derive(Clone, Copy, Debug)]
pub struct Pigment {
    pub k: Rgb,
    pub s: Rgb,
}

impl Pigment {
    /// Derive K and S from a layer's appearance over white and over black.
    pub fn from_appearance(on_white: Rgb, on_black: Rgb) -> Self {
        let mut k = [0.0; 3];
        let mut s = [0.0; 3];
        for i in 0..3 {
            let rw = on_white[i].clamp(0.004, 0.996);
            let rb = on_black[i].clamp(0.001, rw - 0.002);
            let a = 0.5 * (rw + (rb - rw + 1.0) / rb);
            let b = (a * a - 1.0).max(1e-8).sqrt();
            let z = (b * b - (a - rw) * (a - 1.0)) / (b * (1.0 - rw));
            let arcoth = 0.5 * ((z + 1.0) / (z - 1.0).max(1e-8)).ln();
            s[i] = (arcoth / b).max(0.0);
            k[i] = s[i] * (a - 1.0);
        }
        Pigment { k, s }
    }

    /// A transparent glazing pigment (hides very little).
    pub fn transparent(color: Rgb) -> Self {
        Self::with_hiding(color, 0.06)
    }

    /// Aged varnish: a clear film that only absorbs (yellows), with almost
    /// no scattering, so it warms the darks without veiling them.
    pub fn varnish(color: Rgb) -> Self {
        Self::with_hiding(color, 0.004)
    }

    /// Semi-opaque (scumbles, thin body color).
    pub fn semi(color: Rgb) -> Self {
        Self::with_hiding(color, 0.45)
    }

    /// Nearly opaque body color.
    pub fn opaque(color: Rgb) -> Self {
        Self::with_hiding(color, 0.92)
    }

    /// `hiding` = fraction of the over-white appearance that survives over black.
    pub fn with_hiding(color: Rgb, hiding: f32) -> Self {
        let on_black = [color[0] * hiding, color[1] * hiding, color[2] * hiding];
        Self::from_appearance(color, on_black)
    }

    /// Reflectance and transmittance of a layer of thickness `x`.
    #[inline]
    pub fn layer(&self, x: f32) -> (Rgb, Rgb) {
        let mut r = [0.0; 3];
        let mut t = [1.0; 3];
        if x <= 0.0 {
            return ([0.0; 3], [1.0; 3]);
        }
        for i in 0..3 {
            let (k, s) = (self.k[i], self.s[i]);
            if s < 1e-6 {
                // pure absorber
                r[i] = 0.0;
                t[i] = (-k * x).exp();
                continue;
            }
            let a = 1.0 + k / s;
            let b = (a * a - 1.0).max(0.0).sqrt();
            if b < 1e-3 {
                // (nearly) non-absorbing: the b → 0 limit of the formulas below
                let sx = s * x;
                r[i] = sx / (1.0 + a * sx);
                t[i] = 1.0 / (1.0 + a * sx);
                continue;
            }
            let bsx = (b * s * x).min(40.0);
            let (sh, ch) = (bsx.sinh(), bsx.cosh());
            let c = a * sh + b * ch;
            r[i] = sh / c;
            t[i] = b / c;
        }
        (r, t)
    }

    /// Composite a layer of thickness `x` over an opaque substrate.
    #[inline]
    pub fn over(&self, sub: Rgb, x: f32) -> Rgb {
        if x <= 0.0 {
            return sub;
        }
        let (r, t) = self.layer(x);
        let mut out = [0.0; 3];
        for i in 0..3 {
            out[i] = r[i] + t[i] * t[i] * sub[i] / (1.0 - r[i] * sub[i]).max(1e-6);
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trips_unit_layer() {
        let w = [0.6, 0.4, 0.2];
        let b = [0.1, 0.05, 0.02];
        let p = Pigment::from_appearance(w, b);
        let ow = p.over([1.0; 3], 1.0);
        let ob = p.over([0.0; 3], 1.0);
        for i in 0..3 {
            assert!((ow[i] - w[i]).abs() < 0.01, "white {i}: {:?} vs {:?}", ow, w);
            assert!((ob[i] - b[i]).abs() < 0.01, "black {i}: {:?} vs {:?}", ob, b);
        }
    }
}
